#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, ValueEnum)]
pub(crate) enum PackageKind {
    #[default]
    Har,
    Hsp,
}

impl PackageKind {
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            Self::Har => "har",
            Self::Hsp => "hsp",
        }
    }
}

