struct OhosBuildEnvironment {
    vars: HashMap<String, String>,
    wrapper: OsString,
    inner_wrapper: Option<OsString>,
    append_args: String,
}

impl OhosBuildEnvironment {
    fn apply(&self, command: &mut Command) {
        command.envs(&self.vars);
        command.env("UNIFFI_OHOS_RUSTC_WRAPPER", "1");
        command.env(RUSTC_APPEND_ARGS_ENV, &self.append_args);
        command.env("RUSTC_WRAPPER", &self.wrapper);
        suppress_ohos_upstream_type_def_output(command);
        if let Some(inner) = &self.inner_wrapper {
            command.env("UNIFFI_OHOS_INNER_RUSTC_WRAPPER", inner);
        } else {
            command.env_remove("UNIFFI_OHOS_INNER_RUSTC_WRAPPER");
        }
    }
}

fn suppress_ohos_upstream_type_def_output(command: &mut Command) {
    command.env_remove("NAPI_TYPE_DEF_TMP_FOLDER");
    command.env_remove("TYPE_DEF_TMP_PATH");
}

pub(super) fn run_rustc_wrapper_main() -> ! {
    let mut command = match rustc_wrapper_command_from_env() {
        Ok(command) => command,
        Err(error) => {
            eprintln!("UniFFI OHOS rustc wrapper failed: {error:#}");
            std::process::exit(1);
        }
    };

    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        let error = command.exec();
        eprintln!("UniFFI OHOS rustc wrapper failed to exec the compiler: {error}");
        std::process::exit(1);
    }

    #[cfg(not(unix))]
    {
        match command.status() {
            Ok(status) => std::process::exit(status.code().unwrap_or(1)),
            Err(error) => {
                eprintln!("UniFFI OHOS rustc wrapper failed to run the compiler: {error}");
                std::process::exit(1);
            }
        }
    }
}

fn rustc_wrapper_command_from_env() -> Result<Command> {
    let mut argv = env::args_os().skip(1);
    let rustc = argv
        .next()
        .context("Cargo did not pass rustc to the OHOS rustc wrapper")?;
    let args = argv.collect::<Vec<_>>();
    let append_args = decode_wrapper_args(env::var_os(RUSTC_APPEND_ARGS_ENV).as_deref())?;
    rustc_wrapper_command(
        rustc,
        args,
        env::var_os("UNIFFI_OHOS_INNER_RUSTC_WRAPPER"),
        &append_args,
    )
}

fn rustc_wrapper_command(
    rustc: OsString,
    mut args: Vec<OsString>,
    inner_wrapper: Option<OsString>,
    append_args: &[OsString],
) -> Result<Command> {
    let current = env::current_exe()?.into_os_string();
    if same_executable(&rustc, &current)? {
        bail!(
            "Cargo passed the current UniFFI executable as rustc; refusing a recursive OHOS rustc wrapper chain"
        );
    }
    if let Some(inner) = inner_wrapper.as_deref() {
        if same_executable(inner, &current)? {
            bail!(
                "the configured inner rustc wrapper resolves to the current UniFFI executable; refusing a recursive OHOS rustc wrapper chain"
            );
        }
    }
    if rustc_invocation_targets_ohos(&args) {
        args.extend(append_args.iter().cloned());
    }
    let mut command = if let Some(inner_wrapper) = inner_wrapper {
        let mut command = Command::new(inner_wrapper);
        command.arg(&rustc);
        command
    } else {
        Command::new(&rustc)
    };
    command.args(args);
    Ok(command)
}

fn rustc_invocation_targets_ohos(args: &[OsString]) -> bool {
    args.windows(2).any(|window| {
        window[0] == OsStr::new("--target")
            && window[1]
                .to_str()
                .is_some_and(|target| target.ends_with("-linux-ohos"))
    }) || args.iter().any(|arg| {
        arg.to_str()
            .and_then(|arg| arg.strip_prefix("--target="))
            .is_some_and(|target| target.ends_with("-linux-ohos"))
    })
}

fn decode_wrapper_args(encoded: Option<&OsStr>) -> Result<Vec<OsString>> {
    let Some(encoded) = encoded else {
        return Ok(Vec::new());
    };
    let encoded = encoded
        .to_str()
        .context("UniFFI OHOS wrapper arguments are not valid Unicode")?;
    if encoded.is_empty() {
        return Ok(Vec::new());
    }
    let args = encoded
        .split('\x1f')
        .map(OsString::from)
        .collect::<Vec<_>>();
    if args.iter().any(|arg| arg.is_empty()) {
        bail!("UniFFI OHOS wrapper arguments contain an empty token");
    }
    Ok(args)
}

pub(crate) fn build(options: BuildOptions) -> Result<()> {
    if let Some(prepared) = build_internal(options)? {
        prepared.commit()?;
    }
    Ok(())
}

pub(crate) fn build_deferred_hsp(options: BuildOptions) -> Result<PreparedHspInvocation> {
    build_internal(options)?.context("deferred OHOS build did not produce an HSP invocation")
}

fn build_internal(options: BuildOptions) -> Result<Option<PreparedHspInvocation>> {
    validate_package_mode_options(&options)?;
    let ohos_ndk = env::var("OHOS_NDK_HOME").context(
        "OHOS_NDK_HOME is required for the built-in OHOS builder; configure the OHOS SDK/NDK before building Harmony artifacts",
    )?;
    if !Path::new(&ohos_ndk).exists() {
        bail!("OHOS_NDK_HOME does not exist: {ohos_ndk}");
    }

    let arches = parse_arches(&options.arches)?;
    let manifest_path = options
        .manifest_path
        .canonicalize_utf8()
        .unwrap_or_else(|_| options.manifest_path.clone());
    let manifest_dir = manifest_path
        .parent()
        .with_context(|| format!("OHOS manifest has no parent: {manifest_path}"))?;
    let plan = host_plan(&options.cargo_bin, &manifest_path, &options)?;
    // The facade bundle and every embedded contract are invocation inputs.
    // Validate their exact, typed identities before acquiring any output lock,
    // creating a journal/cache, or invoking Cargo/backend tooling.
    let facade_bundle = load_host_facade_bundle(&options.facade_mode)?;
    for package in &plan.packages {
        validate_host_facade_bundle_for_package(&facade_bundle, package)?;
    }
    // An explicitly supplied runtime type is never allowed to flow into a
    // native invocation as an arbitrary Hvigor runtimeOS value, including in
    // no-HAR mode where the remaining publication metadata is intentionally
    // ignored.
    if let Some(sdk_type) = options.compatible_sdk_type.as_deref() {
        RuntimeSdkType::parse(sdk_type)?;
    }
    validate_multi_package_output_overrides(&options, &plan)?;
    let package_metadata = if options.no_har {
        // Pure dist builds do not consume publication metadata.  Keeping this
        // branch free of OHPM/module/SDK validation preserves `--no-har` as a
        // native build mode and prevents stale package staging from affecting
        // the current invocation.
        vec![None; plan.packages.len()]
    } else {
        let sdk = resolve_sdk_compatibility(&options, &ohos_ndk)?;
        let metadata = plan
            .packages
            .iter()
            .map(|package| resolve_oh_package_metadata(&options, package, sdk.clone()))
            .collect::<Result<Vec<_>>>()?;
        ensure_unique_module_names(&plan.packages, &metadata)?;
        metadata.into_iter().map(Some).collect()
    };
    if options.package_kind == PackageKind::Hsp {
        preflight_hsp_environment(
            &options,
            package_metadata
                .iter()
                .map(|value| value.as_ref().expect("HSP metadata is resolved")),
        )?;
    }
    let target_dir = options
        .target_dir
        .clone()
        .map(|p| {
            if p.is_absolute() {
                p
            } else {
                manifest_dir.join(p)
            }
        })
        .unwrap_or_else(|| plan.target_directory.clone());
    let protected_dist_paths = protected_dist_paths(&options, &manifest_path, &plan, &target_dir)?;
    let package_dist_paths = plan
        .packages
        .iter()
        .map(|package| {
            let path = package_dist_dir(&options.dist_dir, package, plan.package_count);
            preflight_dist_output(&path, &protected_dist_paths)
        })
        .collect::<Result<Vec<_>>>()?;
    let mut hsp_outputs = if options.package_kind == PackageKind::Hsp {
        let artifact_root = options
            .dist_dir
            .parent()
            .unwrap_or(options.dist_dir.as_path());
        plan.packages
            .iter()
            .zip(&package_metadata)
            .zip(&package_dist_paths)
            .map(|((package, metadata), dist)| {
                let mut outputs = resolve_hsp_output_paths(
                    &options,
                    artifact_root,
                    package,
                    metadata.as_ref().expect("HSP metadata is resolved"),
                    plan.package_count,
                )?;
                outputs.dist = Some(dist.clone());
                Ok(outputs)
            })
            .collect::<Result<Vec<_>>>()?
    } else {
        Vec::new()
    };
    let package_labels = plan
        .packages
        .iter()
        .map(|package| package.name.clone())
        .collect::<Vec<_>>();
    let planned_hsp_destinations = if options.package_kind == PackageKind::Hsp {
        normalize_hsp_destinations(&mut hsp_outputs, &package_labels)?
    } else {
        Vec::new()
    };
    let mut hsp_owner_plan =
        if options.package_kind == PackageKind::Hsp && !options.output_lock_held {
            Some(DirectOwnerPlan::new(
                planned_hsp_destinations
                    .iter()
                    .map(|destination| InvocationOutputSpec {
                        label: destination.label.clone(),
                        path: destination.path.clone(),
                        is_directory: destination.is_directory,
                    })
                    .collect(),
                "complete OHOS HSP invocation",
            )?)
        } else {
            None
        };
    if options.package_kind == PackageKind::Hsp {
        let after_lock = normalize_hsp_destinations(&mut hsp_outputs, &package_labels)?;
        if after_lock != planned_hsp_destinations {
            bail!("HSP output plan changed while acquiring the complete destination lock set");
        }
    }
    let hsp_path_guards = if let Some(plan) = &hsp_owner_plan {
        plan.path_guards.clone()
    } else if options.package_kind == PackageKind::Hsp {
        capture_existing_path_guards(&planned_hsp_destinations)?
    } else {
        HspPathGuards {
            existing: Vec::new(),
            missing: BTreeSet::new(),
        }
    };
    // All public dist outputs are ownership-checked before package_type_dir()
    // can remove/create type caches or any Cargo/native build can begin.
    let native_path_policy =
        NativePathPolicy::discover(&options, &plan, &manifest_path, &target_dir, &ohos_ndk)?;
    let required_core_so = resolve_required_core_so(&options)?;
    if options.package_kind == PackageKind::Hsp {
        let result = (|| -> Result<Option<PreparedHspInvocation>> {
            let mut prepared = Vec::with_capacity(plan.package_count);
            let mut type_caches = Vec::with_capacity(plan.package_count);
            for (package_index, ((package, metadata), final_package_dist)) in plan
                .packages
                .iter()
                .zip(&package_metadata)
                .zip(&package_dist_paths)
                .enumerate()
            {
                validate_host_facade_bundle_for_package(&facade_bundle, package)?;
                let type_cache = InvocationTypeCache::new(
                    &target_dir,
                    package,
                    options.dts_cache,
                    &facade_bundle,
                )?;
                let type_dir = type_cache.work_dir().to_path_buf();
                let invocation_dist = InvocationDist::new_detached(
                    final_package_dist.clone(),
                    &target_dir.join(".uniffi-hsp-private"),
                )?;
                let expected_so_inventory = build_package_dist_contents(
                    &options,
                    package,
                    &ohos_ndk,
                    &target_dir,
                    &invocation_dist.path,
                    &type_dir,
                    &native_path_policy,
                    &arches,
                    plan.explicit_package_arg,
                    &facade_bundle,
                    required_core_so.as_ref(),
                )?;
                write_dist_owner_marker(&invocation_dist.path)?;
                validate_owned_dist_layout(&invocation_dist.path)?;
                let candidate = build_hsp_candidate(
                    &options,
                    package,
                    &ohos_ndk,
                    metadata.as_ref().expect("HSP package metadata is resolved"),
                    &invocation_dist.path,
                    &hsp_outputs[package_index],
                    Some((&invocation_dist.path, &invocation_dist.final_path)),
                    &expected_so_inventory,
                    &target_dir.join(".uniffi-hsp-private"),
                )?;
                prepared.push(PreparedHspPackage {
                    _invocation_dist: invocation_dist,
                    candidate,
                });
                type_caches.push(type_cache);
            }
            // All packages and all Hvigor candidates exist before any public
            // destination changes. Type-cache commits are private build state and
            // are completed before the single public invocation commit.
            for mut type_cache in type_caches {
                type_cache.commit()?;
            }
            validate_existing_path_guards(&hsp_path_guards)?;
            let prepared = PreparedHspInvocation {
                prepared,
                path_guards: hsp_path_guards,
                owner_plan: hsp_owner_plan.take(),
                hooks: publication_hooks(),
            };
            Ok(Some(prepared))
        })();
        return match result {
            Ok(prepared) => Ok(prepared),
            Err(error) => Err(error),
        };
    }

    for ((package, metadata), final_package_dist) in plan
        .packages
        .iter()
        .zip(&package_metadata)
        .zip(&package_dist_paths)
    {
        validate_host_facade_bundle_for_package(&facade_bundle, package)?;
        // Each package owns a fresh invocation-scoped dist.  Publishing is
        // package-transactional: all selected ABIs and the optional HAR must
        // succeed before this package replaces its prior public dist.  Other
        // workspace packages are never copied into or removed by this build.
        let mut type_cache =
            InvocationTypeCache::new(&target_dir, package, options.dts_cache, &facade_bundle)?;
        let type_dir = type_cache.work_dir().to_path_buf();
        build_package_dist_transactionally_with_lock(
            final_package_dist,
            !options.output_lock_held,
            |package_dist_dir| {
                let _ = build_package_dist_contents(
                    &options,
                    package,
                    &ohos_ndk,
                    &target_dir,
                    package_dist_dir,
                    &type_dir,
                    &native_path_policy,
                    &arches,
                    plan.explicit_package_arg,
                    &facade_bundle,
                    required_core_so.as_ref(),
                )?;
                if !options.no_har {
                    package_output(
                        &options,
                        package,
                        metadata
                            .as_ref()
                            .expect("package metadata is resolved when final packaging is enabled"),
                        package_dist_dir,
                        plan.package_count,
                    )?;
                }
                type_cache.commit()?;
                Ok(())
            },
        )?;
    }
    Ok(None)
}

pub(crate) fn preflight_hsp_host_build(options: &BuildOptions) -> Result<()> {
    planned_hsp_host_build_outputs(options).map(|_| ())
}

pub(crate) fn planned_hsp_host_build_outputs(
    options: &BuildOptions,
) -> Result<Vec<HspOutputPaths>> {
    validate_package_mode_options(options)?;
    if options.package_kind != PackageKind::Hsp {
        return Ok(Vec::new());
    }
    let ohos_ndk = env::var("OHOS_NDK_HOME")
        .context("OHOS_NDK_HOME is required for read-only HSP host-plan preflight")?;
    if !Path::new(&ohos_ndk).exists() {
        bail!("OHOS_NDK_HOME does not exist: {ohos_ndk}");
    }
    parse_arches(&options.arches)?;
    let manifest_path = options
        .manifest_path
        .canonicalize_utf8()
        .unwrap_or_else(|_| options.manifest_path.clone());
    let plan = host_plan(&options.cargo_bin, &manifest_path, options)?;
    validate_multi_package_output_overrides(options, &plan)?;
    let sdk = resolve_sdk_compatibility(options, &ohos_ndk)?;
    let package_metadata = plan
        .packages
        .iter()
        .map(|package| resolve_oh_package_metadata(options, package, sdk.clone()))
        .collect::<Result<Vec<_>>>()?;
    ensure_unique_module_names(&plan.packages, &package_metadata)?;
    preflight_hsp_environment(options, package_metadata.iter())?;
    let artifact_root = options
        .dist_dir
        .parent()
        .unwrap_or(options.dist_dir.as_path());
    let mut outputs = plan
        .packages
        .iter()
        .zip(&package_metadata)
        .map(|(package, metadata)| {
            let mut outputs = resolve_hsp_output_paths(
                options,
                artifact_root,
                package,
                metadata,
                plan.package_count,
            )?;
            outputs.dist = Some(package_dist_dir(
                &options.dist_dir,
                package,
                plan.package_count,
            ));
            Ok(outputs)
        })
        .collect::<Result<Vec<_>>>()?;
    let labels = plan
        .packages
        .iter()
        .map(|package| package.name.clone())
        .collect::<Vec<_>>();
    normalize_hsp_destinations(&mut outputs, &labels)?;
    Ok(outputs)
}

#[derive(Clone, Copy)]
pub(crate) struct GeneratedHspOutputPreflight<'a> {
    pub dist_dir: &'a Utf8Path,
    pub generated_host_package_name: &'a str,
    pub package_name: Option<&'a str>,
    pub runtime_hsp_out: Option<&'a Utf8Path>,
    pub interface_har_out: Option<&'a Utf8Path>,
    pub tgz_out: Option<&'a Utf8Path>,
}

pub(crate) fn preflight_generated_hsp_outputs(
    options: GeneratedHspOutputPreflight<'_>,
) -> Result<()> {
    planned_generated_hsp_outputs(options).map(|_| ())
}

pub(crate) fn planned_generated_hsp_outputs(
    options: GeneratedHspOutputPreflight<'_>,
) -> Result<HspOutputPaths> {
    let artifact_root = options.dist_dir.parent().unwrap_or(options.dist_dir);
    let package_name = options
        .package_name
        .unwrap_or(options.generated_host_package_name);
    validate_oh_package_name(package_name)?;
    let stem = package_name.trim_start_matches('@').replace('/', "-");
    let outputs = HspOutputPaths {
        dist: Some(options.dist_dir.to_path_buf()),
        tgz: options
            .tgz_out
            .map(Utf8Path::to_path_buf)
            .unwrap_or_else(|| artifact_root.join(format!("{stem}.tgz"))),
        runtime_hsp: options
            .runtime_hsp_out
            .map(Utf8Path::to_path_buf)
            .unwrap_or_else(|| artifact_root.join(format!("{stem}.hsp"))),
        interface_har: options
            .interface_har_out
            .map(Utf8Path::to_path_buf)
            .unwrap_or_else(|| artifact_root.join(format!("{stem}-interface.har"))),
        package_source: artifact_root.join("package"),
        module_project: artifact_root.join("module-project"),
        usage: artifact_root.join(format!("{stem}-HSP_USAGE.md")),
    };
    let mut outputs = [outputs];
    normalize_hsp_destinations(
        &mut outputs,
        &[options.generated_host_package_name.to_string()],
    )?;
    Ok(outputs
        .into_iter()
        .next()
        .expect("one generated HSP output plan"))
}

fn validate_multi_package_output_overrides(options: &BuildOptions, plan: &HostPlan) -> Result<()> {
    if plan.packages.len() <= 1 {
        return Ok(());
    }
    if let Some(package_name) = &options.package_name {
        bail!(
            "--package-name `{package_name}` is ambiguous when multiple OHOS packages are selected; pass --package <name> to build a single package"
        );
    }
    if let Some(har_out) = &options.har_out {
        bail!(
            "--har-out `{har_out}` is ambiguous when multiple OHOS packages are selected; pass --package <name> to build a single package"
        );
    }
    for (flag, output) in [
        ("--runtime-hsp-out", options.runtime_hsp_out.as_ref()),
        ("--interface-har-out", options.interface_har_out.as_ref()),
        ("--tgz-out", options.tgz_out.as_ref()),
    ] {
        if let Some(output) = output {
            bail!(
                "{flag} `{output}` is ambiguous when multiple OHOS packages are selected; pass --package <name> to build a single package"
            );
        }
    }
    if let Some(module_name) = &options.module_name {
        bail!(
            "--module-name `{module_name}` is ambiguous when multiple OHOS packages are selected; pass --package <name> to build a single package"
        );
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn build_package_dist_contents(
    options: &BuildOptions,
    package: &HostPackage,
    ohos_ndk: &str,
    target_dir: &Utf8Path,
    package_dist_dir: &Utf8Path,
    type_dir: &Utf8Path,
    native_path_policy: &NativePathPolicy,
    arches: &[Arch],
    explicit_package_arg: bool,
    facade_bundle: &HostFacadeBundle,
    required_core_so: Option<&RequiredCoreSo>,
) -> Result<HspSoInventory> {
    let mut expected_so_inventory = HspSoInventory::new();
    for arch in arches {
        let expected_so = build_arch(
            options,
            package,
            ohos_ndk,
            target_dir,
            package_dist_dir,
            type_dir,
            native_path_policy,
            *arch,
            explicit_package_arg,
            required_core_so,
        )
        .with_context(|| {
            format!(
                "building OHOS package {} arch {}",
                package.name,
                arch.dist_dir()
            )
        })?;
        if expected_so_inventory
            .insert(arch.dist_dir().to_string(), expected_so)
            .is_some()
        {
            bail!("duplicate requested OHOS ABI `{}`", arch.dist_dir());
        }
    }
    write_facade_type_inventory(type_dir, facade_bundle)?;
    emit_index_d_ts(package_dist_dir, type_dir, &package.lib_target_name)?;
    Ok(expected_so_inventory)
}

fn validate_package_mode_options(options: &BuildOptions) -> Result<()> {
    let has_hsp_output = options.runtime_hsp_out.is_some()
        || options.interface_har_out.is_some()
        || options.tgz_out.is_some();
    validate_package_mode_values(
        options.package_kind,
        options.integrated_hsp,
        options.hsp_bundle_name.as_deref(),
        options.har_out.is_some(),
        has_hsp_output,
        options.no_har,
        options.skip_libs,
    )
}

fn validate_package_mode_values(
    package_kind: PackageKind,
    integrated_hsp: bool,
    hsp_bundle_name: Option<&str>,
    has_har_output: bool,
    has_hsp_output: bool,
    no_har: bool,
    skip_libs: bool,
) -> Result<()> {
    match package_kind {
        PackageKind::Har => {
            if integrated_hsp {
                bail!("--integrated-hsp requires --package-type hsp");
            }
            if hsp_bundle_name.is_some() {
                bail!("--hsp-bundle-name requires --package-type hsp");
            }
            if has_hsp_output {
                bail!(
                    "--runtime-hsp-out, --interface-har-out, and --tgz-out require --package-type hsp"
                );
            }
        }
        PackageKind::Hsp => {
            if no_har {
                bail!("--package-type hsp conflicts with --no-har");
            }
            if skip_libs {
                bail!("--package-type hsp conflicts with --skip-libs");
            }
            if has_har_output {
                bail!(
                    "--har-out is a HAR-mode output; use --interface-har-out with --package-type hsp"
                );
            }
            if integrated_hsp {
                if hsp_bundle_name.is_some() {
                    bail!(
                        "--hsp-bundle-name is only valid for a non-integrated HSP; integrated HSP bundleName is intentionally empty"
                    );
                }
            } else {
                let bundle = hsp_bundle_name.with_context(|| {
                    "non-integrated HSP requires --hsp-bundle-name <host.bundle.name>"
                })?;
                validate_hsp_bundle_name(bundle)?;
            }
        }
    }
    Ok(())
}

pub(crate) fn preflight_hsp_frontend(options: HspFrontendPreflight<'_>) -> Result<()> {
    validate_package_mode_values(
        options.package_kind,
        options.integrated_hsp,
        options.hsp_bundle_name,
        options.has_har_output,
        options.has_hsp_output,
        options.no_har,
        options.skip_libs,
    )?;
    if options.package_kind != PackageKind::Hsp {
        return Ok(());
    }

    let ohos_ndk = env::var("OHOS_NDK_HOME").context(
        "OHOS_NDK_HOME is required for HSP preflight before generated output is modified",
    )?;
    if !Path::new(&ohos_ndk).exists() {
        bail!("OHOS_NDK_HOME does not exist: {ohos_ndk}");
    }
    let version = options.compatible_sdk_version.with_context(|| {
        "HSP packaging requires an explicit --compatible-sdk-version before generated output is modified"
    })?;
    let version = validate_sdk_metadata_value(version)?;
    let sdk_type = if let Some(explicit) = options.compatible_sdk_type {
        validate_sdk_metadata_value(explicit)?;
        RuntimeSdkType::parse(explicit)?
    } else {
        discover_sdk_type(&ohos_ndk, options.bisheng)?.with_context(|| {
            "compatible SDK type could not be identified before HSP generation; pass --compatible-sdk-type HarmonyOS or OpenHarmony"
        })?
    };
    let sdk = SdkCompatibility {
        version: version.to_string(),
        sdk_type,
    };
    let api = compatible_sdk_api_level(&sdk)?;
    if api < MIN_HSP_API {
        bail!(
            "HSP compatible SDK API must be at least {MIN_HSP_API}; `{version}` resolves to API {api}"
        );
    }
    let tools = resolve_harmony_tools(options.hvigorw, options.ohpm, options.deveco_sdk_home)?;
    if tools.compile_sdk.api_level < MIN_HSP_API {
        bail!(
            "HSP build requires a DevEco compile SDK at API {MIN_HSP_API} or newer; found API {}",
            tools.compile_sdk.api_level
        );
    }
    resolve_target_sdk_version(&tools.compile_sdk, &sdk, options.target_sdk_version)?;
    preflight_harmony_tools(&tools)
}

fn validate_hsp_bundle_name(value: &str) -> Result<()> {
    if value.len() > 255
        || value.split('.').count() < 2
        || value.split('.').any(|part| {
            part.is_empty()
                || !part
                    .chars()
                    .next()
                    .is_some_and(|character| character.is_ascii_alphabetic())
                || !part
                    .chars()
                    .all(|character| character.is_ascii_alphanumeric() || character == '_')
        })
    {
        bail!(
            "invalid HSP bundleName `{value}`; use dot-separated identifiers beginning with a letter (for example `com.example.app`)"
        );
    }
    Ok(())
}

fn protected_dist_paths(
    options: &BuildOptions,
    manifest_path: &Utf8Path,
    plan: &HostPlan,
    target_dir: &Utf8Path,
) -> Result<Vec<ProtectedDistPath>> {
    let cwd = Utf8PathBuf::from_path_buf(env::current_dir()?)
        .map_err(|path| anyhow::anyhow!("current directory is not utf8: {}", path.display()))?;
    let mut paths = vec![
        ProtectedDistPath {
            label: "current working directory".into(),
            path: cwd,
        },
        ProtectedDistPath {
            label: "input manifest".into(),
            path: manifest_path.to_path_buf(),
        },
        ProtectedDistPath {
            label: "Cargo workspace".into(),
            path: plan.workspace_root.clone(),
        },
        ProtectedDistPath {
            label: "Cargo target directory".into(),
            path: target_dir.to_path_buf(),
        },
    ];
    if let Some(core_manifest) = &options.core_manifest_path {
        paths.push(ProtectedDistPath {
            label: "downstream core manifest".into(),
            path: core_manifest.clone(),
        });
        if let Some(core_root) = core_manifest.parent() {
            paths.push(ProtectedDistPath {
                label: "downstream core package".into(),
                path: core_root.to_path_buf(),
            });
            paths.push(ProtectedDistPath {
                label: "downstream core source directory".into(),
                path: core_root.join("src"),
            });
        }
    }
    for (name, source_root) in &options.additional_source_roots {
        paths.push(ProtectedDistPath {
            label: format!("additional generated/source root `{name}`"),
            path: source_root.clone(),
        });
    }
    for package in &plan.packages {
        let package_root = package.manifest_path.parent().with_context(|| {
            format!(
                "OHOS package manifest has no parent: {}",
                package.manifest_path
            )
        })?;
        paths.push(ProtectedDistPath {
            label: format!("Cargo package `{}`", package.name),
            path: package_root.to_path_buf(),
        });
        paths.push(ProtectedDistPath {
            label: format!("Cargo package `{}` source directory", package.name),
            path: package_root.join("src"),
        });
    }
    for (name, source_root) in &plan.local_source_roots {
        paths.push(ProtectedDistPath {
            label: format!("local Cargo source `{name}`"),
            path: source_root.clone(),
        });
    }
    Ok(paths)
}

fn preflight_dist_output(
    requested: &Utf8Path,
    protected_paths: &[ProtectedDistPath],
) -> Result<Utf8PathBuf> {
    let resolved = preflight_dist_path_safety(requested, protected_paths)?;
    match std::fs::symlink_metadata(&resolved) {
        Ok(metadata) => {
            if metadata.file_type().is_symlink() || !metadata.is_dir() {
                bail!(
                    "OHOS dist output must be a real directory, not a symlink or file: {requested}"
                );
            }
            validate_owned_dist_layout(&resolved).with_context(|| {
                format!(
                    "refusing to replace existing OHOS dist `{requested}` without a valid {DIST_OWNER_MARKER} exact ownership inventory; move/remove the directory or choose a dedicated dist path"
                )
            })?;
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(error).with_context(|| format!("reading OHOS dist output {requested}"));
        }
    }
    Ok(resolved)
}

fn preflight_dist_path_safety(
    requested: &Utf8Path,
    protected_paths: &[ProtectedDistPath],
) -> Result<Utf8PathBuf> {
    let absolute = absolute_output_path(requested)?;
    if std::fs::symlink_metadata(&absolute).is_ok_and(|metadata| metadata.file_type().is_symlink())
    {
        bail!("OHOS dist output must not be a symlink: {requested}");
    }
    let resolved = canonicalize_allow_missing(&absolute)?;
    if resolved.parent().is_none() || resolved.as_str() == "/" {
        bail!("refusing unsafe OHOS dist output at filesystem root: {requested}");
    }

    for protected in protected_paths {
        let protected_path = canonicalize_allow_missing(&absolute_output_path(&protected.path)?)?;
        if protected_path.starts_with(&resolved) {
            bail!(
                "refusing OHOS dist output `{requested}` because it is {} or an ancestor of protected {} `{protected_path}`",
                if protected_path == resolved { "the same path as" } else { "an ancestor of" },
                protected.label,
            );
        }
    }

    Ok(resolved)
}

pub(crate) fn preflight_dist_output_for_generation(
    requested: &Utf8Path,
    protected_paths: &[(String, Utf8PathBuf)],
) -> Result<()> {
    let protected_paths = protected_paths
        .iter()
        .map(|(label, path)| ProtectedDistPath {
            label: label.clone(),
            path: path.clone(),
        })
        .collect::<Vec<_>>();
    preflight_dist_path_safety(requested, &protected_paths).map(|_| ())
}

pub(super) fn write_dist_owner_marker(dist: &Utf8Path) -> Result<OwnedTreeSnapshot> {
    write_owned_tree_marker(dist, DIST_OWNER_MARKER, DIST_OWNER_KIND)
}

pub(super) fn write_dist_owner_marker_with_budget(
    dist: &Utf8Path,
    budget: &mut TraversalBudget,
) -> Result<OwnedTreeSnapshot> {
    let entries = collect_tree_inventory_ignoring_with_limits(
        dist,
        &[DIST_OWNER_MARKER],
        MAX_HSP_ARCHIVE_ENTRIES,
        MAX_HSP_ARCHIVE_TOTAL_BYTES,
        budget,
    )?;
    let marker = OwnedTreeMarker {
        owner: DIST_OWNER_KIND.into(),
        schema_version: OWNED_TREE_SCHEMA_VERSION,
        generation: new_generation_id(),
        identity: None,
        root_identity: persistent_fs_identity(dist, true)?,
        entries: entries
            .iter()
            .map(|(path, entry)| OwnedTreeMarkerEntry {
                path: path.clone(),
                kind: entry.kind.clone(),
                sha256: entry.sha256.clone(),
                identity: entry.identity.clone(),
                link_target: entry.link_target.clone(),
                resolved_target: entry.resolved_target.clone(),
            })
            .collect(),
    };
    let mut text = serde_json::to_string_pretty(&marker)?;
    text.push('\n');
    let marker_path = dist.join(DIST_OWNER_MARKER);
    let mut marker_file = OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&marker_path)
        .with_context(|| format!("creating new {DIST_OWNER_KIND} marker {marker_path}"))?;
    marker_file
        .write_all(text.as_bytes())
        .with_context(|| format!("writing {DIST_OWNER_KIND} marker {marker_path}"))?;
    marker_file.sync_all()?;
    validate_owned_dist_layout_with_budget(dist, budget)
}

pub(super) fn validate_owned_dist_layout(dist: &Utf8Path) -> Result<OwnedTreeSnapshot> {
    validate_owned_tree(dist, DIST_OWNER_MARKER, DIST_OWNER_KIND)
}

pub(super) fn validate_owned_dist_layout_with_budget(
    dist: &Utf8Path,
    budget: &mut TraversalBudget,
) -> Result<OwnedTreeSnapshot> {
    let marker_path = dist.join(DIST_OWNER_MARKER);
    budget.consume(
        marker_path.as_str(),
        "file",
        std::fs::symlink_metadata(&marker_path)?.len(),
    )?;
    let (marker, marker_identity) =
        read_owned_tree_marker(dist, DIST_OWNER_MARKER, DIST_OWNER_KIND)?;
    let mut entries = BTreeMap::new();
    for value in marker.entries {
        validate_inventory_path(&value.path, DIST_OWNER_MARKER)?;
        if !owned_entry_shape_valid(
            &value.kind,
            &value.sha256,
            &value.link_target,
            &value.resolved_target,
        ) {
            bail!(
                "ownership inventory entry has an invalid shape: {}",
                value.path
            );
        }
        let path = value.path.clone();
        if entries
            .insert(
                path.clone(),
                OwnedTreeEntry {
                    kind: value.kind,
                    sha256: value.sha256,
                    identity: value.identity,
                    link_target: value.link_target,
                    resolved_target: value.resolved_target,
                },
            )
            .is_some()
        {
            bail!("ownership inventory contains duplicate path: {path}");
        }
    }
    let actual = collect_tree_inventory_ignoring_with_limits(
        dist,
        &[DIST_OWNER_MARKER],
        MAX_HSP_ARCHIVE_ENTRIES,
        MAX_HSP_ARCHIVE_TOTAL_BYTES,
        budget,
    )?;
    if entries != actual {
        bail!(
            "{DIST_OWNER_KIND} tree no longer matches its exact ownership inventory; refusing replacement"
        );
    }
    Ok(OwnedTreeSnapshot {
        generation: marker.generation,
        identity: marker.identity,
        root_identity: marker.root_identity,
        marker_identity: Some(marker_identity),
        entries,
        mutation_tokens: None,
    })
}

#[cfg(test)]
fn build_package_dist_transactionally<Build>(final_path: &Utf8Path, build: Build) -> Result<()>
where
    Build: FnOnce(&Utf8Path) -> Result<()>,
{
    build_package_dist_transactionally_with_lock(final_path, true, build)
}

fn build_package_dist_transactionally_with_lock<Build>(
    final_path: &Utf8Path,
    acquire_lock: bool,
    build: Build,
) -> Result<()>
where
    Build: FnOnce(&Utf8Path) -> Result<()>,
{
    let final_path = absolute_output_path(final_path)?;
    let _lock = if acquire_lock {
        let lock_path = output_lock_path(&final_path)?;
        Some(OutputLock::acquire(&lock_path, "OHOS dist")?)
    } else {
        None
    };
    let final_path = preflight_dist_output(&final_path, &[])?;
    let previous = if final_path.exists() {
        Some(validate_owned_dist_layout(&final_path)?)
    } else {
        None
    };
    let invocation_dist = InvocationDist::new(final_path)?;
    build(&invocation_dist.path)?;
    write_dist_owner_marker(&invocation_dist.path)?;
    validate_owned_dist_layout(&invocation_dist.path)?;
    invocation_dist.publish_with(previous.as_ref(), validate_owned_dist_layout, |path| {
        remove_owned_tree_for_cleanup(
            path,
            DIST_OWNER_MARKER,
            DIST_OWNER_KIND,
            previous
                .as_ref()
                .context("previous OHOS dist backup lacks its committed owner snapshot")?,
        )
        .with_context(|| format!("removing previous OHOS dist backup {path}"))
    })
}

#[cfg(test)]
#[allow(dead_code)]
fn replace_directory_transactionally(
    source: &Utf8Path,
    destination: &Utf8Path,
    previous: Option<&OwnedTreeSnapshot>,
) -> Result<()> {
    replace_directory_transactionally_with(source, destination, previous, |path| {
        remove_owned_tree_for_cleanup(
            path,
            DIST_OWNER_MARKER,
            DIST_OWNER_KIND,
            previous.context("previous OHOS dist backup lacks its committed owner snapshot")?,
        )
        .with_context(|| format!("removing previous OHOS dist backup {path}"))
    })
}

#[cfg(test)]
fn replace_directory_transactionally_with<RemoveBackup>(
    source: &Utf8Path,
    destination: &Utf8Path,
    previous: Option<&OwnedTreeSnapshot>,
    remove_backup: RemoveBackup,
) -> Result<()>
where
    RemoveBackup: FnOnce(&Utf8Path) -> Result<()>,
{
    replace_directory_transactionally_with_validation(
        source,
        destination,
        previous,
        validate_owned_dist_layout,
        remove_backup,
    )
}

impl NativePathPolicy {
    fn discover(
        options: &BuildOptions,
        plan: &HostPlan,
        host_manifest: &Utf8Path,
        target_dir: &Utf8Path,
        ohos_ndk: &str,
    ) -> Result<Self> {
        let mut remaps = Vec::<PathRemap>::new();
        let mut seen = BTreeSet::<Utf8PathBuf>::new();
        let mut add = |path: &Utf8Path, destination: String| -> Result<()> {
            let lexical = absolute_output_path(path)?;
            let canonical = canonicalize_allow_missing(&lexical)?;
            for source in [lexical, canonical] {
                if source.as_str() == "/" || !seen.insert(source.clone()) {
                    continue;
                }
                if source.as_str().contains('\x1f') {
                    bail!("cannot encode Rust path remap for a path containing unit separator: {source}");
                }
                remaps.push(PathRemap {
                    source,
                    destination: destination.clone(),
                });
            }
            Ok(())
        };

        if let Some(core_manifest) = &options.core_manifest_path {
            if let Some(root) = core_manifest.parent() {
                add(root, "/uniffi/source/core".into())?;
            }
        }
        if let Some(root) = host_manifest.parent() {
            add(root, "/uniffi/source/host".into())?;
        }
        for (name, root) in &options.additional_source_roots {
            add(
                root,
                format!("/uniffi/source/extra/{}", stable_virtual_segment(name)),
            )?;
        }
        let dependency_metadata = MetadataCommand::new()
            .cargo_path(&options.cargo_bin)
            .manifest_path(host_manifest.as_std_path())
            .exec()
            .with_context(|| {
                format!("resolving local OHOS Cargo sources for reproducible path remapping: {host_manifest}")
            })?;
        let mut local_source_roots = dependency_metadata
            .packages
            .iter()
            .filter(|package| package.source.is_none())
            .filter_map(|package| {
                let manifest =
                    Utf8PathBuf::from_path_buf(package.manifest_path.clone().into_std_path_buf())
                        .ok()?;
                Some((
                    format!("{}-{}", package.name, package.version),
                    manifest.parent()?.to_path_buf(),
                ))
            })
            .collect::<Vec<_>>();
        local_source_roots.extend(plan.local_source_roots.iter().cloned());
        local_source_roots.sort();
        local_source_roots.dedup();
        for (index, (name, root)) in local_source_roots.iter().enumerate() {
            add(
                root,
                format!(
                    "/uniffi/source/local/{index}-{}",
                    stable_virtual_segment(name)
                ),
            )?;
        }
        add(&plan.workspace_root, "/uniffi/source/workspace".into())?;
        add(target_dir, "/uniffi/build/target".into())?;

        let temp_root = Utf8PathBuf::from_path_buf(env::temp_dir()).map_err(|path| {
            anyhow::anyhow!("temporary directory is not utf8: {}", path.display())
        })?;
        add(&temp_root, "/uniffi/build/temp".into())?;
        add(Utf8Path::new(ohos_ndk), "/uniffi/sdk/ohos".into())?;
        if let Some(hos_ndk) = resolve_hos_ndk(ohos_ndk) {
            if let Ok(hos_ndk) = Utf8PathBuf::from_path_buf(hos_ndk) {
                add(&hos_ndk, "/uniffi/sdk/harmony".into())?;
            }
        }
        if let Some(deveco_sdk) = options
            .deveco_sdk_home
            .clone()
            .or_else(|| env::var("DEVECO_SDK_HOME").ok().map(Utf8PathBuf::from))
        {
            add(&deveco_sdk, "/uniffi/sdk/deveco".into())?;
        }

        let home = env::var("HOME").ok().map(Utf8PathBuf::from);
        if let Some(cargo_home) = env::var("CARGO_HOME")
            .ok()
            .map(Utf8PathBuf::from)
            .or_else(|| home.as_ref().map(|home| home.join(".cargo")))
        {
            add(&cargo_home, "/uniffi/toolchain/cargo".into())?;
        }
        if let Some(rustup_home) = env::var("RUSTUP_HOME")
            .ok()
            .map(Utf8PathBuf::from)
            .or_else(|| home.as_ref().map(|home| home.join(".rustup")))
        {
            add(&rustup_home, "/uniffi/toolchain/rustup".into())?;
        }
        if let Some(sysroot) = rustc_sysroot()? {
            add(&sysroot, "/uniffi/toolchain/sysroot".into())?;
        }
        if let Some(home) = &home {
            add(home, "/uniffi/home".into())?;
        }

        // Keep the policy model in the prompt-requested most-specific to
        // broadest order.  merge_encoded_rustflags() reverses this when
        // encoding because rustc intentionally applies the last matching
        // --remap-path-prefix rule.
        remaps.sort_by(|left, right| {
            right
                .source
                .as_str()
                .len()
                .cmp(&left.source.as_str().len())
                .then_with(|| left.source.cmp(&right.source))
        });
        Ok(Self { remaps })
    }

    fn for_invocation(&self, paths: &[(&Utf8Path, &str)]) -> Result<Self> {
        let mut policy = self.clone();
        for (path, destination) in paths {
            let lexical = absolute_output_path(path)?;
            let canonical = canonicalize_allow_missing(&lexical)?;
            for source in [lexical, canonical] {
                if source.as_str() == "/"
                    || policy.remaps.iter().any(|remap| remap.source == source)
                {
                    continue;
                }
                if source.as_str().contains('\x1f') {
                    bail!("cannot encode Rust path remap for a path containing unit separator: {source}");
                }
                policy.remaps.push(PathRemap {
                    source: source.clone(),
                    destination: (*destination).to_string(),
                });
            }
        }
        policy.remaps.sort_by(|left, right| {
            right
                .source
                .as_str()
                .len()
                .cmp(&left.source.as_str().len())
                .then_with(|| left.source.cmp(&right.source))
        });
        Ok(policy)
    }
}

fn stable_virtual_segment(value: &str) -> String {
    let segment = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '_'
            }
        })
        .collect::<String>();
    if segment.is_empty() {
        "package".into()
    } else {
        segment
    }
}

fn rustc_sysroot() -> Result<Option<Utf8PathBuf>> {
    let rustc = env::var("RUSTC").unwrap_or_else(|_| "rustc".into());
    let output = match Command::new(&rustc).args(["--print", "sysroot"]).output() {
        Ok(output) => output,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(error).with_context(|| format!("running `{rustc} --print sysroot`"))
        }
    };
    if !output.status.success() {
        return Ok(None);
    }
    let value = String::from_utf8(output.stdout).context("rustc sysroot path is not UTF-8")?;
    let value = value.trim();
    if value.is_empty() {
        Ok(None)
    } else {
        Ok(Some(Utf8PathBuf::from(value)))
    }
}

fn parse_arches(arches: &[String]) -> Result<Vec<Arch>> {
    if arches.is_empty() {
        Ok(vec![Arch::Arm64, Arch::X86_64])
    } else {
        arches.iter().map(|arch| Arch::parse(arch)).collect()
    }
}

/// Validate the architecture spellings before a multi-participant HSP
/// coordinator creates durable publication anchors.  The deferred builder
/// validates them again when it consumes the complete options, but that is
/// intentionally too late for a zero-side-effect argument error.
pub(crate) fn preflight_hsp_arches(arches: &[String]) -> Result<()> {
    parse_arches(arches).map(|_| ())
}

fn host_plan(
    cargo_bin: &str,
    manifest_path: &Utf8Path,
    options: &BuildOptions,
) -> Result<HostPlan> {
    let metadata = MetadataCommand::new()
        .cargo_path(cargo_bin)
        .manifest_path(manifest_path.as_std_path())
        .no_deps()
        .exec()
        .with_context(|| format!("running cargo metadata for OHOS host crate {manifest_path}"))?;

    let explicit_package = resolve_package_filter(options.package.as_deref(), &options.cargo_args)?;
    let explicit_package_arg = explicit_package.is_some();
    let mut eligible_packages = Vec::new();
    let workspace_members = metadata
        .workspace_members
        .iter()
        .filter_map(|member_id| metadata.packages.iter().find(|p| &p.id == member_id))
        .collect::<Vec<_>>();
    let candidates = if workspace_members.is_empty() {
        metadata.packages.iter().collect::<Vec<_>>()
    } else {
        workspace_members
    };

    for package in candidates {
        if !options.skip_napi_check && !has_napi_ohos_dependency(package) {
            continue;
        }
        if !has_ohos_library_target(package) {
            continue;
        }
        eligible_packages.push(host_package(package)?);
    }
    let package_count = eligible_packages.len();
    let packages = eligible_packages
        .into_iter()
        .filter(|package| {
            explicit_package.as_ref().map_or(true, |filter| {
                let package_spec = format!("{}@{}", package.name, package.version);
                &package.name == filter || &package_spec == filter
            })
        })
        .collect::<Vec<_>>();

    if packages.is_empty() {
        if let Some(filter) = explicit_package {
            bail!("no OHOS-capable package matched `{filter}`");
        }
        bail!(
            "no OHOS-capable package found; add napi-derive-ohos or pass --skip-napi-check if this is intentional"
        );
    }

    if !options.skip_check {
        check_napi_versions(cargo_bin, manifest_path)?;
    }

    let workspace_root =
        Utf8PathBuf::from_path_buf(metadata.workspace_root.clone().into_std_path_buf())
            .map_err(|p| anyhow::anyhow!("Cargo workspace root is not utf8: {}", p.display()))?;
    let mut local_source_roots = metadata
        .packages
        .iter()
        .filter(|package| package.source.is_none())
        .filter_map(|package| {
            let manifest =
                Utf8PathBuf::from_path_buf(package.manifest_path.clone().into_std_path_buf())
                    .ok()?;
            Some((
                format!("{}-{}", package.name, package.version),
                manifest.parent()?.to_path_buf(),
            ))
        })
        .collect::<Vec<_>>();
    local_source_roots.sort();
    local_source_roots.dedup();

    Ok(HostPlan {
        target_directory: Utf8PathBuf::from_path_buf(
            metadata.target_directory.clone().into_std_path_buf(),
        )
        .map_err(|p| anyhow::anyhow!("cargo metadata target dir is not utf8: {}", p.display()))?,
        workspace_root,
        local_source_roots,
        packages,
        package_count,
        explicit_package_arg,
    })
}

fn has_napi_ohos_dependency(package: &Package) -> bool {
    package
        .dependencies
        .iter()
        .any(|dep| dep.name == "napi-derive-ohos")
}

fn has_ohos_library_target(package: &Package) -> bool {
    package.targets.iter().any(|target| {
        target
            .kind
            .iter()
            .any(|kind| matches!(kind.to_string().as_str(), "cdylib" | "lib"))
    })
}

fn host_package(package: &Package) -> Result<HostPackage> {
    let lib_target = package
        .targets
        .iter()
        .find(|target| target.kind.iter().any(|kind| kind.to_string() == "cdylib"))
        .or_else(|| {
            package
                .targets
                .iter()
                .find(|target| target.kind.iter().any(|kind| kind.to_string() == "lib"))
        })
        .with_context(|| format!("OHOS package {} has no lib target", package.name))?;
    let manifest_path =
        Utf8PathBuf::from_path_buf(package.manifest_path.clone().into_std_path_buf())
            .map_err(|p| anyhow::anyhow!("package manifest path is not utf8: {}", p.display()))?;
    Ok(HostPackage {
        cargo_package_id: package.id.repr.clone(),
        name: package.name.to_string(),
        version: package.version.to_string(),
        description: package.description.clone(),
        authors: package.authors.clone(),
        license: package.license.clone(),
        manifest_path,
        lib_target_name: lib_target.name.clone(),
    })
}

fn check_napi_versions(cargo_bin: &str, manifest_path: &Utf8Path) -> Result<()> {
    let metadata = MetadataCommand::new()
        .cargo_path(cargo_bin)
        .manifest_path(manifest_path.as_std_path())
        .exec()
        .with_context(|| {
            format!("running full cargo metadata for OHOS version checks: {manifest_path}")
        })?;
    for name in ["napi-ohos", "napi-derive-ohos"] {
        let package = metadata
            .packages
            .iter()
            .find(|package| package.name.as_str() == name)
            .with_context(|| {
                format!("failed to find {name}; pass --skip-check to bypass this check")
            })?;
        let min = cargo_metadata::semver::Version::parse("1.1.0")?;
        if package.version < min {
            bail!(
                "{name} must be >= 1.1.0 for OHOS builds; found {}. Pass --skip-check to bypass this check",
                package.version
            );
        }
    }
    Ok(())
}

fn package_arg_from_cargo_args(args: &[String]) -> Option<String> {
    args.iter()
        .position(|arg| arg == "-p" || arg == "--package")
        .and_then(|idx| args.get(idx + 1).cloned())
        .or_else(|| {
            args.iter()
                .find_map(|arg| {
                    arg.strip_prefix("-p=")
                        .or_else(|| arg.strip_prefix("--package="))
                })
                .map(str::to_string)
        })
}

fn resolve_package_filter(
    option_package: Option<&str>,
    cargo_args: &[String],
) -> Result<Option<String>> {
    let cargo_package = package_arg_from_cargo_args(cargo_args);
    match (option_package, cargo_package) {
        (Some(option_package), Some(cargo_package)) if option_package != cargo_package => {
            bail!(
                "conflicting OHOS package filters: --package {option_package} and trailing cargo args package {cargo_package}"
            )
        }
        (Some(option_package), _) => Ok(Some(option_package.to_string())),
        (_, Some(cargo_package)) => Ok(Some(cargo_package)),
        _ => Ok(None),
    }
}

fn has_package_arg(args: &[String]) -> bool {
    package_arg_from_cargo_args(args).is_some()
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub(super) enum FacadeBundleMode {
    Required,
    #[default]
    RawOnly,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct HostFacadeComponentIdentity {
    component: String,
    namespace: String,
    native_export_prefix: String,
    interface_abi_digest: String,
    contract_file: String,
    contract_sha256: String,
    identity_export: String,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(super) struct HostFacadeBundle {
    pub(super) host_bundle_schema_version: u64,
    pub(super) fingerprint: String,
    pub(super) package_name: String,
    pub(super) lib_target: String,
    pub(super) host_composite_identity: String,
    components: Vec<HostFacadeComponentIdentity>,
    pub(super) contracts: Vec<HostFacadeBundleEntry>,
    pub(super) type_sidecars: Vec<HostFacadeBundleEntry>,
    #[serde(skip)]
    pub(super) mode: FacadeBundleMode,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct HostFacadeBundleEntry {
    pub(super) file: String,
    pub(super) sha256: String,
    pub(super) content: String,
}

impl HostFacadeBundle {
    fn empty() -> Result<Self> {
        let mut bundle = Self {
            host_bundle_schema_version: HOST_BUNDLE_SCHEMA_VERSION,
            fingerprint: String::new(),
            package_name: String::new(),
            lib_target: String::new(),
            host_composite_identity: sha256_bytes(b"raw-only"),
            components: Vec::new(),
            contracts: Vec::new(),
            type_sidecars: Vec::new(),
            mode: FacadeBundleMode::RawOnly,
        };
        bundle.fingerprint = bundle.computed_fingerprint()?;
        Ok(bundle)
    }

    fn computed_fingerprint(&self) -> Result<String> {
        let entry = |value: &HostFacadeBundleEntry| {
            serde_json::json!({
                "file": value.file,
                "sha256": value.sha256,
                "content": value.content,
            })
        };
        let payload = serde_json::json!({
            "packageName": self.package_name,
            "libTarget": self.lib_target,
            "hostCompositeIdentity": self.host_composite_identity,
            "components": self.components,
            "contracts": self.contracts.iter().map(entry).collect::<Vec<_>>(),
            "typeSidecars": self.type_sidecars.iter().map(entry).collect::<Vec<_>>(),
        });
        Ok(sha256_bytes(&serde_json::to_vec(&payload)?))
    }
}

fn load_host_facade_bundle(mode: &FacadeMode) -> Result<HostFacadeBundle> {
    let FacadeMode::Required(path) = mode else {
        // Raw-only is an explicit lower-level build mode.  It never guesses
        // that an absent contract means the compiled host has no streams.
        return HostFacadeBundle::empty();
    };
    let bytes = read_verified_regular_file(path)
        .with_context(|| format!("reading OHOS facade bundle {path}"))?;
    preflight_exact_schema_version(
        &bytes,
        "hostBundleSchemaVersion",
        HOST_BUNDLE_SCHEMA_VERSION,
        &format!("OHOS facade bundle {path}"),
    )?;
    let mut bundle: HostFacadeBundle = serde_json::from_slice(&bytes)
        .with_context(|| format!("parsing OHOS facade bundle {path}"))?;
    bundle.mode = FacadeBundleMode::Required;
    if bundle.host_bundle_schema_version != HOST_BUNDLE_SCHEMA_VERSION {
        bail!(
            "unsupported hostBundleSchemaVersion in {path}: expected {HOST_BUNDLE_SCHEMA_VERSION}, got {}",
            bundle.host_bundle_schema_version
        );
    }
    if bundle.fingerprint != bundle.computed_fingerprint()? {
        bail!("OHOS facade bundle fingerprint mismatch in {path}");
    }
    validate_host_facade_bundle_canonical_order(&bundle, path)?;
    validate_host_facade_bundle_entries(&bundle, path)?;
    validate_host_facade_bundle_contracts(&bundle, path)?;
    preflight_host_facade_bundle_semantics(&bundle, path)?;
    Ok(bundle)
}

fn validate_host_facade_bundle_canonical_order(
    bundle: &HostFacadeBundle,
    path: &Utf8Path,
) -> Result<()> {
    if bundle
        .components
        .windows(2)
        .any(|pair| pair[0].component >= pair[1].component)
    {
        bail!("OHOS facade bundle components are not in canonical component order in {path}");
    }
    for (entries, label) in [
        (&bundle.contracts, "contracts"),
        (&bundle.type_sidecars, "type sidecars"),
    ] {
        if entries.windows(2).any(|pair| pair[0].file >= pair[1].file) {
            bail!("OHOS facade bundle {label} are not in canonical file order in {path}");
        }
    }
    Ok(())
}

fn validate_host_facade_bundle_for_package(
    bundle: &HostFacadeBundle,
    package: &HostPackage,
) -> Result<()> {
    if bundle.mode == FacadeBundleMode::RawOnly {
        return Ok(());
    }
    if bundle.package_name != package.name || bundle.lib_target != package.lib_target_name {
        bail!(
            "OHOS facade bundle host identity `{}/{}` does not match selected Cargo host `{}/{}`",
            bundle.package_name,
            bundle.lib_target,
            package.name,
            package.lib_target_name
        );
    }
    // Recompute through the producer's shared canonical algorithm rather
    // than serializing the richer bundle component records here. Contract
    // digests and bridge sentinels remain separately bound by the bundle
    // fingerprint.
    let expected = uniffi_bindgen_javascript::host_crates::composite_host_identity(
        &bundle.package_name,
        &bundle.lib_target,
        &bundle
            .components
            .iter()
            .map(|component| {
                (
                    component.component.clone(),
                    component.namespace.clone(),
                    component.native_export_prefix.clone(),
                    component.interface_abi_digest.clone(),
                )
            })
            .collect::<Vec<_>>(),
    )?;
    if expected != bundle.host_composite_identity {
        bail!("OHOS facade bundle host composite identity mismatch");
    }
    if bundle.components.is_empty()
        || bundle.contracts.len() != bundle.components.len()
        || bundle.type_sidecars.len() != bundle.components.len()
    {
        bail!(
            "required OHOS facade bundle must bind every component to one contract and one canonical type sidecar"
        );
    }
    let contracts = bundle
        .contracts
        .iter()
        .map(|entry| (entry.file.as_str(), entry.sha256.as_str()))
        .collect::<BTreeMap<_, _>>();
    let mut components = BTreeSet::new();
    let mut namespaces = BTreeSet::new();
    let mut native_export_prefixes = BTreeSet::new();
    let mut sentinels = BTreeSet::new();
    for component in &bundle.components {
        uniffi_bindgen::interface::validate_harmony_component_identity(
            &component.component,
            &component.namespace,
        )
        .with_context(|| {
            format!(
                "invalid OHOS facade component identity `{}/{}`",
                component.component, component.namespace
            )
        })?;
        if component.native_export_prefix
            != uniffi_bindgen::interface::native_export_prefix_for_component(&component.component)
        {
            bail!(
                "OHOS facade component `{}` has an invalid native export prefix",
                component.component
            );
        }
        validate_sha256(
            &component.interface_abi_digest,
            "component interface ABI digest",
            &package.manifest_path,
        )?;
        if !components.insert(component.component.as_str())
            || !namespaces.insert(component.namespace.as_str())
            || !native_export_prefixes.insert(component.native_export_prefix.as_str())
            || !sentinels.insert(component.identity_export.as_str())
        {
            bail!("duplicate OHOS facade component, namespace, native export prefix, or bridge identity sentinel");
        }
        validate_sha256(
            &component.contract_sha256,
            "component contract digest",
            &package.manifest_path,
        )?;
        let expected_export =
            bridge_identity_export(&component.native_export_prefix, &component.contract_sha256);
        if component.identity_export != expected_export
            || contracts.get(component.contract_file.as_str())
                != Some(&component.contract_sha256.as_str())
        {
            bail!(
                "OHOS facade component `{}` is not bound to its exact contract/bridge identity",
                component.component
            );
        }
    }
    let expected_sidecars = bundle
        .components
        .iter()
        .map(|component| format!("{}.ohos-extra-types.d.ts", component.component))
        .collect::<BTreeSet<_>>();
    let actual_sidecars = bundle
        .type_sidecars
        .iter()
        .map(|entry| entry.file.clone())
        .collect::<BTreeSet<_>>();
    if actual_sidecars != expected_sidecars {
        bail!(
            "required OHOS facade bundle type sidecars must exactly match its component identities"
        );
    }
    Ok(())
}

/// Validate every checksummed contract while the bundle is still a read-only
/// invocation input.  Type-cache creation and Cargo must never discover an
/// invalid contract after they have already changed state.
fn validate_host_facade_bundle_contracts(bundle: &HostFacadeBundle, path: &Utf8Path) -> Result<()> {
    if bundle.mode == FacadeBundleMode::RawOnly {
        return Ok(());
    }
    if bundle.components.len() != bundle.contracts.len() {
        bail!(
            "required OHOS facade bundle must bind every component to one exact contract in {path}"
        );
    }
    let contract_entries = bundle
        .contracts
        .iter()
        .map(|entry| (entry.file.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut components = BTreeSet::new();
    let mut namespaces = BTreeSet::new();
    let mut prefixes = BTreeSet::new();
    let mut files = BTreeSet::new();
    let mut exports = BTreeSet::new();
    for component in &bundle.components {
        uniffi_bindgen::interface::validate_harmony_component_identity(
            &component.component,
            &component.namespace,
        )
        .with_context(|| {
            format!(
                "invalid OHOS facade component identity `{}/{}` in {path}",
                component.component, component.namespace
            )
        })?;
        if !components.insert(component.component.as_str())
            || !namespaces.insert(component.namespace.as_str())
            || !prefixes.insert(component.native_export_prefix.as_str())
            || !files.insert(component.contract_file.as_str())
            || !exports.insert(component.identity_export.as_str())
        {
            bail!("OHOS facade bundle has duplicate component identity fields in {path}");
        }
        if component.native_export_prefix
            != uniffi_bindgen::interface::native_export_prefix_for_component(&component.component)
        {
            bail!(
                "OHOS facade bundle component `{}` has an invalid nativeExportPrefix in {path}",
                component.component
            );
        }
    }
    let identities = bundle
        .components
        .iter()
        .map(|component| {
            (
                component.component.as_str(),
                (
                    component.namespace.as_str(),
                    component.native_export_prefix.as_str(),
                ),
            )
        })
        .collect::<BTreeMap<_, _>>();
    for component in &bundle.components {
        let entry = contract_entries
            .get(component.contract_file.as_str())
            .with_context(|| {
                format!(
                "OHOS facade bundle component `{}` references a missing contract `{}` in {path}",
                component.component, component.contract_file
            )
            })?;
        if entry.sha256 != component.contract_sha256 {
            bail!(
                "OHOS facade bundle component `{}` checksum does not match contract `{}` in {path}",
                component.component,
                component.contract_file
            );
        }
        let contract = parse_harmony_facade_contract(entry.content.as_bytes(), path)?;
        if contract.component != component.component
            || contract.namespace != component.namespace
            || contract.native_export_prefix != component.native_export_prefix
            || component.native_export_prefix
                != uniffi_bindgen::interface::native_export_prefix_for_component(
                    &component.component,
                )
            || component.identity_export
                != bridge_identity_export(
                    &component.native_export_prefix,
                    &component.contract_sha256,
                )
        {
            bail!(
                "OHOS facade bundle component `{}` does not exactly match its contract identity in {path}",
                component.component
            );
        }
        validate_harmony_facade_contract_owners(&contract, &identities, path)?;
    }
    Ok(())
}

/// Exercise the same raw declaration, stream-contract, generated-name, and
/// bridge-sentinel checks that declaration emission uses, while the bundle is
/// still a read-only input.  A cache, Cargo invocation, or output directory
/// must never be the first place an invalid embedded sidecar is discovered.
fn preflight_host_facade_bundle_semantics(
    bundle: &HostFacadeBundle,
    path: &Utf8Path,
) -> Result<()> {
    if bundle.mode == FacadeBundleMode::RawOnly {
        return Ok(());
    }

    let owned_defs = parse_owned_bundle_type_defs(bundle, path)?;
    let defs = owned_defs
        .iter()
        .flat_map(|owned| owned.defs.iter().cloned())
        .collect::<Vec<_>>();
    let mut owner_type_names = BTreeMap::new();
    let mut owner_native_export_prefixes = BTreeMap::new();
    for owned in &owned_defs {
        owner_type_names.insert(
            owned.projection.component.clone(),
            collect_declared_type_names(&owned.defs),
        );
        owner_native_export_prefixes.insert(
            owned.projection.component.clone(),
            owned.projection.native_export_prefix.clone(),
        );
    }
    validate_raw_type_def_uniqueness(&defs)?;

    let mut contracts = bundle
        .contracts
        .iter()
        .map(|entry| {
            parse_harmony_facade_contract(entry.content.as_bytes(), Utf8Path::new(&entry.file))
        })
        .collect::<Result<Vec<_>>>()?;
    contracts.sort_by(|left, right| left.component.cmp(&right.component));
    for contract in &contracts {
        validate_harmony_facade_contract_owner_type_references(
            contract,
            &owner_type_names,
            &owner_native_export_prefixes,
            path,
        )?;
    }

    let inventory = FacadeTypeInventory {
        facade_inventory_schema_version: FACADE_INVENTORY_SCHEMA_VERSION,
        facade_mode: "required".into(),
        host_composite_identity: bundle.host_composite_identity.clone(),
        components: bundle.components.clone(),
        bundle_fingerprint: bundle.fingerprint.clone(),
        type_definitions: bundle
            .type_sidecars
            .iter()
            .map(|entry| FacadeInventoryFile {
                file: entry.file.clone(),
                sha256: entry.sha256.clone(),
            })
            .collect(),
        contracts: bundle
            .contracts
            .iter()
            .map(|entry| FacadeInventoryFile {
                file: entry.file.clone(),
                sha256: entry.sha256.clone(),
            })
            .collect(),
    };
    validate_compiled_bridge_identities(&defs, &inventory, &contracts)?;
    let _ = FacadeExports::from_owned_type_defs_and_contracts(owned_defs, contracts)?;
    Ok(())
}

fn parse_owned_bundle_type_defs(
    bundle: &HostFacadeBundle,
    path: &Utf8Path,
) -> Result<Vec<OwnedFacadeTypeDefs>> {
    let sidecars = bundle
        .type_sidecars
        .iter()
        .map(|entry| (entry.file.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut owned = Vec::new();
    for component in &bundle.components {
        let sidecar_file = format!("{}.ohos-extra-types.d.ts", component.component);
        let entry = sidecars.get(sidecar_file.as_str()).with_context(|| {
            format!(
                "OHOS facade bundle component `{}` is missing canonical sidecar `{sidecar_file}` in {path}",
                component.component
            )
        })?;
        let contract = parse_bundle_component_contract(bundle, component, path)?;
        let input_stream_type = RawInputStreamTypeExpectation::from_contract(&contract);
        let defs = parse_canonical_ohos_type_defs(
            entry.content.as_bytes(),
            &format!("{path}:{}", entry.file),
            &input_stream_type,
        )?;
        owned.push(OwnedFacadeTypeDefs::new(component, defs)?);
    }
    let flattened = owned
        .iter()
        .flat_map(|component| component.defs.iter().cloned())
        .collect::<Vec<_>>();
    validate_raw_type_def_uniqueness(&flattened)?;
    Ok(owned)
}

/// Resolve a component's contract through its exact checked `contractFile`
/// binding.  This is deliberately not a filename suffix or native-name
/// lookup: the component identity in the bundle is the authoritative owner
/// of the sidecar's generic input-stream allowance.
fn parse_bundle_component_contract(
    bundle: &HostFacadeBundle,
    component: &HostFacadeComponentIdentity,
    path: &Utf8Path,
) -> Result<HarmonyFacadeContract> {
    let entry = bundle
        .contracts
        .iter()
        .find(|entry| entry.file == component.contract_file)
        .with_context(|| {
            format!(
                "OHOS facade bundle component `{}` references a missing contract `{}` in {path}",
                component.component, component.contract_file
            )
        })?;
    if entry.sha256 != component.contract_sha256
        || sha256_bytes(entry.content.as_bytes()) != entry.sha256
    {
        bail!(
            "OHOS facade bundle component `{}` has an invalid checked contract binding `{}` in {path}",
            component.component,
            component.contract_file
        );
    }
    let contract = parse_harmony_facade_contract(entry.content.as_bytes(), path)?;
    if contract.component != component.component
        || contract.namespace != component.namespace
        || contract.native_export_prefix != component.native_export_prefix
    {
        bail!(
            "OHOS facade bundle component `{}` does not exactly match its contract identity in {path}",
            component.component
        );
    }
    Ok(contract)
}

/// Re-read the exact installed contract before materializing a type-cache
/// inventory.  This makes cache creation enforce the same component contract
/// binding used by the read-only bundle preflight and later declaration
/// emission.
fn read_installed_bundle_component_contract(
    type_dir: &Utf8Path,
    bundle: &HostFacadeBundle,
    component: &HostFacadeComponentIdentity,
) -> Result<HarmonyFacadeContract> {
    let entry = bundle
        .contracts
        .iter()
        .find(|entry| entry.file == component.contract_file)
        .with_context(|| {
            format!(
                "OHOS facade bundle component `{}` references a missing installed contract `{}`",
                component.component, component.contract_file
            )
        })?;
    if entry.sha256 != component.contract_sha256 {
        bail!(
            "OHOS facade bundle component `{}` has a mismatched contract checksum for `{}`",
            component.component,
            component.contract_file
        );
    }
    let contract_path = type_dir.join(&entry.file);
    let bytes = read_verified_regular_file(&contract_path)?;
    if sha256_bytes(&bytes) != entry.sha256 {
        bail!("OHOS facade contract changed after bundle installation: {contract_path}");
    }
    let contract = parse_harmony_facade_contract(&bytes, &contract_path)?;
    if contract.component != component.component
        || contract.namespace != component.namespace
        || contract.native_export_prefix != component.native_export_prefix
    {
        bail!(
            "installed OHOS facade contract `{}` does not exactly match component `{}`",
            component.contract_file,
            component.component
        );
    }
    Ok(contract)
}

fn bridge_identity_export(native_export_prefix: &str, contract_digest: &str) -> String {
    // Keep the consumer's re-computation on the producer's single canonical
    // export-name rule.  The digest key is not itself a globally exported
    // name: a composite addon may carry one sentinel per component.
    uniffi_bindgen_javascript::flavors::napi::ohos_bridge_identity_export_for_prefix(
        native_export_prefix,
        contract_digest,
    )
}

fn is_raw_bridge_identity_export(name: &str) -> bool {
    // Do not hide a user callable merely because its name contains the
    // sentinel substring.  Generated names are exactly
    // `<ffi-prefix>_uniffiohosbridgeidentity<64 encoded-digest chars>`;
    // bundle/inventory validation subsequently compares this candidate with
    // the exact expected identity export for its component.
    let Some((native_export_prefix, encoded_digest)) =
        name.rsplit_once("_uniffiohosbridgeidentity")
    else {
        return false;
    };
    native_export_prefix.starts_with("ffi_")
        && native_export_prefix.len() > "ffi_".len()
        && native_export_prefix
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
        && encoded_digest.len() == 64
        && encoded_digest
            .bytes()
            .all(|byte| matches!(byte, b'a'..=b'p'))
}

fn validate_host_facade_bundle_entries(bundle: &HostFacadeBundle, path: &Utf8Path) -> Result<()> {
    let mut names = BTreeSet::new();
    for (entry, suffix, label) in bundle
        .contracts
        .iter()
        .map(|entry| (entry, ".ohos-facade.json", "contract"))
        .chain(
            bundle
                .type_sidecars
                .iter()
                .map(|entry| (entry, ".ohos-extra-types.d.ts", "type sidecar")),
        )
    {
        let file = Utf8Path::new(&entry.file);
        if file.file_name() != Some(entry.file.as_str()) || !entry.file.ends_with(suffix) {
            bail!("unsafe OHOS facade {label} file `{}` in {path}", entry.file);
        }
        if !names.insert(entry.file.as_str()) {
            bail!(
                "duplicate OHOS facade bundle file `{}` in {path}",
                entry.file
            );
        }
        if entry.sha256 != sha256_bytes(entry.content.as_bytes()) {
            bail!(
                "OHOS facade bundle {label} checksum mismatch for `{}` in {path}",
                entry.file
            );
        }
    }
    // Type sidecars are invocation inputs, not best-effort declaration
    // fragments.  Parse their complete canonical grammar through each
    // component's exact checked facade contract before a type-cache lock,
    // work directory, Cargo invocation, or public declaration exists.
    if bundle.type_sidecars.len() != bundle.components.len() {
        bail!(
            "required OHOS facade bundle must bind every component to one canonical type sidecar in {path}"
        );
    }
    let sidecars = bundle
        .type_sidecars
        .iter()
        .map(|entry| (entry.file.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut type_defs = Vec::new();
    for component in &bundle.components {
        let sidecar_file = format!("{}.ohos-extra-types.d.ts", component.component);
        let entry = sidecars.get(sidecar_file.as_str()).with_context(|| {
            format!(
                "OHOS facade bundle component `{}` is missing canonical sidecar `{sidecar_file}` in {path}",
                component.component
            )
        })?;
        let contract = parse_bundle_component_contract(bundle, component, path)?;
        let input_stream_type = RawInputStreamTypeExpectation::from_contract(&contract);
        type_defs.extend(parse_canonical_ohos_type_defs(
            entry.content.as_bytes(),
            &format!("{path}:{}", entry.file),
            &input_stream_type,
        )?);
    }
    validate_raw_type_def_uniqueness(&type_defs)?;
    Ok(())
}

impl TypeCacheIdentity {
    pub(super) fn new(package: &HostPackage, bundle: &HostFacadeBundle) -> Result<Self> {
        let canonical_manifest = package
            .manifest_path
            .canonicalize_utf8()
            .unwrap_or_else(|_| package.manifest_path.clone());
        Ok(Self {
            canonical_manifest: canonical_manifest.to_string(),
            cargo_package_id: package.cargo_package_id.clone(),
            package_name: package.name.clone(),
            lib_target: package.lib_target_name.clone(),
            host_composite_identity: bundle.host_composite_identity.clone(),
            host_bundle_schema_version: bundle.host_bundle_schema_version,
            bundle_fingerprint: bundle.fingerprint.clone(),
            facade_contract_schema_version: FACADE_CONTRACT_SCHEMA_VERSION,
            facade_mode: match bundle.mode {
                FacadeBundleMode::Required => "required",
                FacadeBundleMode::RawOnly => "raw-only",
            }
            .to_string(),
        })
    }

    pub(super) fn digest(&self) -> Result<String> {
        Ok(sha256_bytes(&serde_json::to_vec(self)?))
    }
}

impl InvocationTypeCache {
    fn new(
        target_dir: &Utf8Path,
        package: &HostPackage,
        dts_cache: bool,
        bundle: &HostFacadeBundle,
    ) -> Result<Self> {
        let identity = TypeCacheIdentity::new(package, bundle)?;
        let work_entries = expected_type_work_entries(bundle)?;
        let stem = format!("{}-{}", package.name, identity.digest()?);
        InvocationTypeCache::begin(
            TypeCachePlan {
                target_dir: target_dir.to_path_buf(),
                identity,
                work_entries,
                stem,
                primary_entry: None,
                dts_cache,
            },
            |work| install_facade_bundle(work, bundle),
        )
    }
}

pub(super) fn expected_type_work_entries(bundle: &HostFacadeBundle) -> Result<BTreeSet<String>> {
    let mut entries = BTreeSet::from([FACADE_INVENTORY_FILE.to_string()]);
    for entry in bundle.contracts.iter().chain(&bundle.type_sidecars) {
        validate_inventory_path(&entry.file, TYPE_CACHE_WORK_MARKER)?;
        if !entries.insert(entry.file.clone()) {
            bail!(
                "OHOS facade bundle file `{}` collides with a type-work inventory entry",
                entry.file
            );
        }
    }
    Ok(entries)
}

fn install_facade_bundle(
    work: &mut TypeCacheInitialization<'_>,
    bundle: &HostFacadeBundle,
) -> Result<()> {
    let mut occupied = BTreeSet::from([
        FACADE_INVENTORY_FILE,
        TYPE_CACHE_OWNER_MARKER,
        TYPE_CACHE_WORK_MARKER,
    ]);
    for entry in bundle.contracts.iter().chain(&bundle.type_sidecars) {
        if !occupied.insert(entry.file.as_str()) {
            bail!(
                "OHOS facade bundle file `{}` collides with a type-cache control file",
                entry.file
            );
        }
        let path = work.work_dir().join(&entry.file);
        let mut file = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&path)
            .with_context(|| format!("creating invocation facade bundle file {path}"))?;
        file.write_all(entry.content.as_bytes())
            .with_context(|| format!("writing invocation facade bundle file {path}"))?;
        file.sync_all()?;
        work.record_completed_entry(&entry.file)?;
    }
    Ok(())
}

fn write_facade_type_inventory(type_dir: &Utf8Path, bundle: &HostFacadeBundle) -> Result<()> {
    let mut type_definitions = Vec::new();
    let mut parsed_type_defs = Vec::new();
    let mut contracts = Vec::new();
    match bundle.mode {
        FacadeBundleMode::RawOnly => {
            if !bundle.components.is_empty()
                || !bundle.contracts.is_empty()
                || !bundle.type_sidecars.is_empty()
            {
                bail!(
                    "raw-only OHOS facade bundle cannot install generated contracts or canonical type sidecars"
                );
            }
        }
        FacadeBundleMode::Required => {
            if bundle.components.len() != bundle.contracts.len()
                || bundle.components.len() != bundle.type_sidecars.len()
            {
                bail!(
                    "required OHOS facade bundle must bind every component to one contract and one canonical type sidecar"
                );
            }
            let sidecars = bundle
                .type_sidecars
                .iter()
                .map(|entry| (entry.file.as_str(), entry))
                .collect::<BTreeMap<_, _>>();
            for component in &bundle.components {
                let contract =
                    read_installed_bundle_component_contract(type_dir, bundle, component)?;
                let input_stream_type = RawInputStreamTypeExpectation::from_contract(&contract);
                let sidecar_file = format!("{}.ohos-extra-types.d.ts", component.component);
                let entry = sidecars.get(sidecar_file.as_str()).with_context(|| {
                    format!(
                        "OHOS facade bundle component `{}` is missing canonical sidecar `{sidecar_file}`",
                        component.component
                    )
                })?;
                let path = type_dir.join(&entry.file);
                let bytes = read_verified_regular_file(&path)?;
                let actual = sha256_bytes(&bytes);
                if actual != entry.sha256 {
                    bail!("OHOS canonical type sidecar changed after bundle installation: {path}");
                }
                parsed_type_defs.extend(parse_canonical_ohos_type_defs(
                    &bytes,
                    path.as_str(),
                    &input_stream_type,
                )?);
                type_definitions.push(serde_json::json!({
                    "file": entry.file,
                    "sha256": actual,
                }));
                contracts.push(serde_json::json!({
                    "file": component.contract_file,
                    "sha256": component.contract_sha256,
                }));
            }
        }
    }
    validate_raw_type_def_uniqueness(&parsed_type_defs)?;
    type_definitions.sort_by(|left, right| left["file"].as_str().cmp(&right["file"].as_str()));
    contracts.sort_by(|left, right| left["file"].as_str().cmp(&right["file"].as_str()));
    let inventory = serde_json::json!({
        "facadeInventorySchemaVersion": FACADE_INVENTORY_SCHEMA_VERSION,
        "facadeMode": match bundle.mode {
            FacadeBundleMode::Required => "required",
            FacadeBundleMode::RawOnly => "raw-only",
        },
        "hostCompositeIdentity": bundle.host_composite_identity,
        "components": bundle.components,
        "bundleFingerprint": bundle.fingerprint,
        "typeDefinitions": type_definitions,
        "contracts": contracts,
    });
    let inventory_path = type_dir.join(FACADE_INVENTORY_FILE);
    let mut text = serde_json::to_string_pretty(&inventory)?;
    text.push('\n');
    let mut file = OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&inventory_path)
        .with_context(|| format!("creating exact OHOS facade inventory {inventory_path}"))?;
    file.write_all(text.as_bytes())?;
    file.sync_all()?;
    complete_type_work_file_from_marker(type_dir, FACADE_INVENTORY_FILE)?;
    Ok(())
}

fn package_dist_dir(root: &Utf8Path, package: &HostPackage, package_count: usize) -> Utf8PathBuf {
    if package_count <= 1 {
        root.to_path_buf()
    } else {
        root.join(&package.name)
    }
}

fn package_output(
    options: &BuildOptions,
    package: &HostPackage,
    metadata: &OhosPackageMetadata,
    package_dist_dir: &Utf8Path,
    package_count: usize,
) -> Result<()> {
    match options.package_kind {
        PackageKind::Har => {
            package_har(options, package, metadata, package_dist_dir, package_count)
        }
        PackageKind::Hsp => {
            bail!("internal error: HSP packaging requires the independent Cargo SO inventory")
        }
    }
}

fn package_har(
    options: &BuildOptions,
    package: &HostPackage,
    metadata: &OhosPackageMetadata,
    package_dist_dir: &Utf8Path,
    package_count: usize,
) -> Result<()> {
    let artifact_root = options
        .dist_dir
        .parent()
        .unwrap_or(options.dist_dir.as_path())
        .to_path_buf();
    let package_dir = package_stage_dir(&artifact_root, package, package_count);
    let requested_har_out = resolve_har_out(
        options.har_out.as_deref(),
        &artifact_root,
        package,
        package_count,
    );
    package_har_with(
        &package_dir,
        &requested_har_out,
        Some(&options.dist_dir),
        || {
            stage_har_package(
                package_dist_dir,
                &package_dir,
                &package.lib_target_name,
                metadata,
                options.skip_libs,
            )
        },
        |har_out| build_hvigor_har(options, metadata, &package_dir, har_out),
    )
}

fn package_har_with<Stage, Build>(
    package_dir: &Utf8Path,
    requested_har_out: &Utf8Path,
    dist_dir: Option<&Utf8Path>,
    stage: Stage,
    build: Build,
) -> Result<()>
where
    Stage: FnOnce() -> Result<()>,
    Build: FnOnce(&Utf8Path) -> Result<()>,
{
    // This preflight is deliberately the first mutating boundary.  It resolves
    // existing symlinks and prospective missing paths before stage() can
    // delete or rebuild package_dir, so an unsafe output never destroys a
    // previous staging tree or HAR.
    if let Some(dist_dir) = dist_dir {
        let dist_dir = canonicalize_allow_missing(&absolute_output_path(dist_dir)?)?;
        let requested_har_out =
            canonicalize_allow_missing(&absolute_output_path(requested_har_out)?)?;
        if requested_har_out.starts_with(&dist_dir) {
            bail!(
                "HAR output path must not be inside the build-owned OHOS dist directory: {requested_har_out}"
            );
        }
    }
    let har_out = prepare_har_output_path(requested_har_out, Some(package_dir))?;
    stage()?;
    build(&har_out)
}

#[derive(Debug)]
struct HspArchiveMembers {
    tgz: Vec<u8>,
    runtime_name: String,
    runtime_hsp: Vec<u8>,
    interface_name: String,
    interface_har: Vec<u8>,
}

fn build_hsp_candidate(
    options: &BuildOptions,
    package: &HostPackage,
    ohos_ndk: &str,
    metadata: &OhosPackageMetadata,
    package_dist_dir: &Utf8Path,
    outputs: &HspOutputPaths,
    dist_publication: Option<(&Utf8Path, &Utf8Path)>,
    expected_so_inventory: &HspSoInventory,
    scratch_parent: &Utf8Path,
) -> Result<HspCandidate> {
    let outputs = outputs.clone();
    if let Some((_, final_dist)) = dist_publication {
        if outputs.dist.as_deref() != Some(final_dist) {
            bail!("HSP dist publication does not match the immutable invocation output plan");
        }
    }

    let generation_root =
        create_unique_invocation_directory(scratch_parent, ".uniffi-hsp-generation")?;
    let staged_package = generation_root.join("package");
    stage_package(
        package_dist_dir,
        &staged_package,
        &package.lib_target_name,
        metadata,
        PackageKind::Hsp,
        options.integrated_hsp,
        false,
        Some(expected_so_inventory),
    )?;
    let strip = ohos_llvm_tool_path(ohos_ndk, "llvm-strip");
    let expected_runtime_so_inventory = normalize_staged_hsp_so_inventory(
        &staged_package.join("libs"),
        expected_so_inventory,
        &strip,
    )?;

    let sdk = metadata.sdk.as_ref().with_context(|| {
        "HSP packaging requires --compatible-sdk-version and a resolved compatible SDK type"
    })?;
    let mut tools = resolve_harmony_har_tools(options)?;
    let staged_project = generation_root.join("module-project");
    let staged_module = staged_project.join("library");
    copy_dir_recursive(&staged_package, &staged_module)?;
    write_hvigor_hsp_project(
        &staged_project,
        &staged_module,
        metadata,
        sdk,
        &tools,
        options.target_sdk_version.as_deref(),
        options.integrated_hsp,
        options.hsp_bundle_name.as_deref(),
    )?;
    let members = build_hvigor_hsp_from_project(
        options,
        package,
        metadata,
        &staged_project,
        sdk,
        &mut tools,
        expected_so_inventory,
        &expected_runtime_so_inventory,
    )?;

    let staged_tgz = generation_root.join("release.tgz");
    let staged_runtime = generation_root.join("runtime.hsp");
    let staged_interface = generation_root.join("interface.har");
    write_durable_file(&staged_tgz, &members.tgz)?;
    write_durable_file(&staged_runtime, &members.runtime_hsp)?;
    write_durable_file(&staged_interface, &members.interface_har)?;
    ensure_member_file_identity(&staged_runtime, &members.runtime_hsp, &members.runtime_name)?;
    ensure_member_file_identity(
        &staged_interface,
        &members.interface_har,
        &members.interface_name,
    )?;
    let staged_usage = generation_root.join("HSP_USAGE.md");
    write_durable_file(
        &staged_usage,
        render_hsp_usage(metadata, options.integrated_hsp).as_bytes(),
    )?;

    let mut staged = vec![
        (staged_tgz, outputs.tgz.clone(), false),
        (staged_runtime, outputs.runtime_hsp.clone(), false),
        (staged_interface, outputs.interface_har.clone(), false),
        (staged_package, outputs.package_source.clone(), true),
        (staged_project, outputs.module_project.clone(), true),
        (staged_usage, outputs.usage.clone(), false),
    ];
    if let Some((staged_dist, final_dist)) = dist_publication {
        staged.push((staged_dist.to_path_buf(), final_dist.to_path_buf(), true));
    }
    Ok(HspCandidate {
        _generation_root: generation_root,
        outputs,
        staged,
    })
}

fn hsp_archive_stem(
    package: &HostPackage,
    metadata: &OhosPackageMetadata,
    package_count: usize,
) -> String {
    let mut stem = metadata.name.trim_start_matches('@').replace('/', "-");
    if package_count > 1 {
        stem.push('-');
        stem.push_str(&package.lib_target_name);
    }
    stem
}

fn resolve_hsp_output_paths(
    options: &BuildOptions,
    artifact_root: &Utf8Path,
    package: &HostPackage,
    metadata: &OhosPackageMetadata,
    package_count: usize,
) -> Result<HspOutputPaths> {
    let stem = hsp_archive_stem(package, metadata, package_count);
    let package_source = package_stage_dir(artifact_root, package, package_count);
    let module_project = if package_count <= 1 {
        artifact_root.join("module-project")
    } else {
        artifact_root.join("module-project").join(&package.name)
    };
    Ok(HspOutputPaths {
        dist: None,
        tgz: options
            .tgz_out
            .clone()
            .unwrap_or_else(|| artifact_root.join(format!("{stem}.tgz"))),
        runtime_hsp: options
            .runtime_hsp_out
            .clone()
            .unwrap_or_else(|| artifact_root.join(format!("{stem}.hsp"))),
        interface_har: options
            .interface_har_out
            .clone()
            .unwrap_or_else(|| artifact_root.join(format!("{stem}-interface.har"))),
        package_source,
        module_project,
        usage: artifact_root.join(format!("{stem}-HSP_USAGE.md")),
    })
}

fn render_hsp_usage(metadata: &OhosPackageMetadata, integrated: bool) -> String {
    let integration = if integrated {
        "This is an integrated HSP. The consumer must enable `buildOption.strictMode.useNormalizedOHMUrl: true`; Hvigor binds the consumer bundleName and signing identity during the consumer build."
    } else {
        "This is an application-bound HSP. The consumer bundleName and signing identity must match the bundle used to build this package."
    };
    format!(
        "# {} Harmony HSP usage\n\nDepend on the generated `.tgz` directly from the consuming HAP/HSP module, using the exact package name as the dependency key:\n\n```json5\n{{\n  \"dependencies\": {{\n    \"{}\": \"file:./libs/<generated>.tgz\"\n  }}\n}}\n```\n\n{integration}\n\nHSP dependencies are not transitive and circular HSP dependencies are forbidden. A HAR that depends on an HSP becomes application-internal and must not be published to a second- or third-party repository. Do not use the extracted runtime `.hsp` or Interface `.har` as the app dependency; they are verification/debug artifacts for the same tgz generation.\n",
        metadata.name, metadata.name
    )
}

pub(super) fn verify_hsp_publication(
    output_sets: &[HspOutputPaths],
    budget: &SharedTraversalBudget,
) -> Result<()> {
    for outputs in output_sets {
        let runtime = read_verified_regular_file_bounded_with_budget(
            &absolute_output_path(&outputs.runtime_hsp)?,
            MAX_HSP_ARCHIVE_MEMBER_BYTES,
            "published runtime HSP",
            &mut budget.borrow_mut(),
        )?;
        let interface = read_verified_regular_file_bounded_with_budget(
            &absolute_output_path(&outputs.interface_har)?,
            MAX_HSP_ARCHIVE_MEMBER_BYTES,
            "published Interface HAR",
            &mut budget.borrow_mut(),
        )?;
        let tgz = read_verified_regular_file_bounded_with_budget(
            &absolute_output_path(&outputs.tgz)?,
            MAX_HSP_ARCHIVE_COMPRESSED_BYTES,
            "published HSP tgz",
            &mut budget.borrow_mut(),
        )?;
        let members = parse_hsp_tgz(&tgz)?;
        if runtime != members.runtime_hsp || interface != members.interface_har {
            bail!("published HSP standalone artifacts do not match the committed tgz members");
        }
        if let Some(dist) = &outputs.dist {
            validate_owned_dist_layout_with_budget(
                &absolute_output_path(dist)?,
                &mut budget.borrow_mut(),
            )
            .context("validating dist committed with the HSP generation")?;
        }
    }
    Ok(())
}

fn finalize_publication_directory_candidate(
    candidate: &Utf8Path,
    budget: &mut TraversalBudget,
) -> Result<()> {
    let copied_dist_owner = candidate.join(DIST_OWNER_MARKER);
    if copied_dist_owner.exists() {
        remove_current_regular_file_for_cleanup_with_budget(
            &copied_dist_owner,
            "copied stale dist owner marker",
            budget,
        )
        .with_context(|| format!("removing copied stale dist owner marker {copied_dist_owner}"))?;
        write_dist_owner_marker_with_budget(candidate, budget)
            .context("rebinding copied dist owner marker to publication candidate")?;
    }
    Ok(())
}

pub(super) fn publication_hooks() -> PublicationHooks {
    PublicationHooks {
        finalize_directory_candidate: finalize_publication_directory_candidate,
        verify_hsp_outputs: verify_hsp_publication,
    }
}

