#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct FacadeTypeInventory {
    facade_inventory_schema_version: u64,
    facade_mode: String,
    host_composite_identity: String,
    components: Vec<HostFacadeComponentIdentity>,
    bundle_fingerprint: String,
    type_definitions: Vec<FacadeInventoryFile>,
    contracts: Vec<FacadeInventoryFile>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct FacadeInventoryFile {
    file: String,
    sha256: String,
}

fn load_facade_type_inventory(type_dir: &Utf8Path) -> Result<FacadeTypeInventory> {
    let inventory_path = type_dir.join(FACADE_INVENTORY_FILE);
    let inventory_bytes = read_verified_regular_file(&inventory_path)?;
    let inventory: FacadeTypeInventory = serde_json::from_slice(&inventory_bytes)
        .with_context(|| format!("parsing OHOS facade inventory {inventory_path}"))?;
    if inventory.facade_inventory_schema_version != FACADE_INVENTORY_SCHEMA_VERSION {
        bail!(
            "unsupported facadeInventorySchemaVersion in {inventory_path}: expected {FACADE_INVENTORY_SCHEMA_VERSION}, got {}",
            inventory.facade_inventory_schema_version
        );
    }
    validate_sha256(
        &inventory.bundle_fingerprint,
        "bundle fingerprint",
        &inventory_path,
    )?;
    let mut seen = BTreeSet::new();
    for (entry, contract) in inventory
        .type_definitions
        .iter()
        .map(|entry| (entry, false))
        .chain(inventory.contracts.iter().map(|entry| (entry, true)))
    {
        let file_path = Utf8Path::new(&entry.file);
        if file_path.file_name() != Some(entry.file.as_str())
            || entry.file.is_empty()
            || (contract && !entry.file.ends_with(".ohos-facade.json"))
            || (!contract && !entry.file.ends_with(".ohos-extra-types.d.ts"))
        {
            bail!(
                "unsafe OHOS facade inventory path `{}` in {inventory_path}",
                entry.file
            );
        }
        if !seen.insert(entry.file.as_str()) {
            bail!(
                "duplicate OHOS facade inventory file `{}` in {inventory_path}",
                entry.file
            );
        }
        validate_sha256(&entry.sha256, "file checksum", &inventory_path)?;
        let path = type_dir.join(&entry.file);
        let bytes = read_verified_regular_file(&path)?;
        let actual = sha256_bytes(&bytes);
        if actual != entry.sha256 {
            bail!("OHOS facade inventory checksum mismatch for {path}");
        }
    }
    match inventory.facade_mode.as_str() {
        "raw-only" => {
            if !inventory.components.is_empty()
                || !inventory.type_definitions.is_empty()
                || !inventory.contracts.is_empty()
            {
                bail!(
                    "raw-only OHOS facade inventory cannot contain generated contracts or canonical type sidecars"
                );
            }
        }
        "required" => {
            if inventory.components.is_empty()
                || inventory.type_definitions.len() != inventory.components.len()
                || inventory.contracts.len() != inventory.components.len()
            {
                bail!(
                    "required OHOS facade inventory must bind every component to one contract and one canonical type sidecar"
                );
            }
            let expected_type_definitions = inventory
                .components
                .iter()
                .map(|component| format!("{}.ohos-extra-types.d.ts", component.component))
                .collect::<BTreeSet<_>>();
            let actual_type_definitions = inventory
                .type_definitions
                .iter()
                .map(|entry| entry.file.clone())
                .collect::<BTreeSet<_>>();
            if actual_type_definitions != expected_type_definitions {
                bail!(
                    "required OHOS facade inventory type sidecars must exactly match its component identities"
                );
            }
            let expected_contracts = inventory
                .components
                .iter()
                .map(|component| component.contract_file.clone())
                .collect::<BTreeSet<_>>();
            let actual_contracts = inventory
                .contracts
                .iter()
                .map(|entry| entry.file.clone())
                .collect::<BTreeSet<_>>();
            if actual_contracts != expected_contracts {
                bail!(
                    "required OHOS facade inventory contracts must exactly match their component contractFile bindings"
                );
            }
        }
        other => bail!("unknown OHOS facade mode `{other}`"),
    }
    Ok(inventory)
}

fn validate_sha256(value: &str, label: &str, path: &Utf8Path) -> Result<()> {
    if value.len() != 64
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        bail!("OHOS facade inventory {path} has invalid {label}");
    }
    Ok(())
}

fn load_harmony_facade_contracts(
    type_dir: &Utf8Path,
    inventory: &FacadeTypeInventory,
) -> Result<Vec<HarmonyFacadeContract>> {
    if inventory.facade_mode == "raw-only" {
        return Ok(Vec::new());
    }
    let mut contracts = Vec::new();
    for component in &inventory.components {
        contracts.push(read_inventory_component_contract(
            type_dir, inventory, component,
        )?);
    }
    contracts.sort_by(|a, b| a.component.cmp(&b.component));
    Ok(contracts)
}

/// Resolve the declaration consumer's input-stream allowance through the
/// exact `contractFile` recorded for this component.  The cache inventory is
/// checksummed, but its sidecar is not permitted to select a contract by
/// filename suffix, logical name, or bridge sentinel.
fn read_inventory_component_contract(
    type_dir: &Utf8Path,
    inventory: &FacadeTypeInventory,
    component: &HostFacadeComponentIdentity,
) -> Result<HarmonyFacadeContract> {
    let entry = inventory
        .contracts
        .iter()
        .find(|entry| entry.file == component.contract_file)
        .with_context(|| {
            format!(
                "OHOS facade inventory component `{}` references a missing contract `{}`",
                component.component, component.contract_file
            )
        })?;
    if entry.sha256 != component.contract_sha256 {
        bail!(
            "OHOS facade inventory component `{}` has a mismatched contract checksum for `{}`",
            component.component,
            component.contract_file
        );
    }
    let contract_path = type_dir.join(&entry.file);
    let bytes = read_verified_regular_file(&contract_path)?;
    if sha256_bytes(&bytes) != entry.sha256 {
        bail!("OHOS facade contract changed before consumption: {contract_path}");
    }
    let contract = parse_harmony_facade_contract(&bytes, &contract_path)?;
    if contract.component != component.component
        || contract.namespace != component.namespace
        || contract.native_export_prefix != component.native_export_prefix
    {
        bail!(
            "OHOS facade inventory component `{}` does not exactly match its contract identity",
            component.component
        );
    }
    Ok(contract)
}

fn validate_compiled_bridge_identities(
    defs: &[TypeDefLine],
    inventory: &FacadeTypeInventory,
    contracts: &[HarmonyFacadeContract],
) -> Result<()> {
    let raw_sentinels = defs
        .iter()
        .filter(|def| def.kind == "fn" && is_raw_bridge_identity_export(&def.name))
        .collect::<Vec<_>>();
    if inventory.facade_mode == "raw-only" {
        if !inventory.components.is_empty() || !contracts.is_empty() || !raw_sentinels.is_empty() {
            bail!("raw-only OHOS facade mode cannot consume generated bridge identity metadata");
        }
        return Ok(());
    }
    if inventory.facade_mode != "required" {
        bail!("unknown OHOS facade mode `{}`", inventory.facade_mode);
    }
    validate_sha256(
        &inventory.host_composite_identity,
        "host composite identity",
        Utf8Path::new(FACADE_INVENTORY_FILE),
    )?;
    if inventory.components.len() != contracts.len()
        || raw_sentinels.len() != inventory.components.len()
    {
        bail!(
            "compiled OHOS bridge identity/component coverage mismatch: {} sentinels, {} identities, {} contracts",
            raw_sentinels.len(),
            inventory.components.len(),
            contracts.len()
        );
    }
    let contract_components = contracts
        .iter()
        .map(|contract| contract.component.as_str())
        .collect::<BTreeSet<_>>();
    let inventory_contracts = inventory
        .contracts
        .iter()
        .map(|entry| (entry.file.as_str(), entry.sha256.as_str()))
        .collect::<BTreeMap<_, _>>();
    let mut expected_sentinels = BTreeSet::new();
    let mut expected_components = BTreeSet::new();
    let mut expected_namespaces = BTreeSet::new();
    let mut expected_native_export_prefixes = BTreeSet::new();
    for component in &inventory.components {
        validate_sha256(
            &component.interface_abi_digest,
            "component interface ABI digest",
            Utf8Path::new(FACADE_INVENTORY_FILE),
        )?;
        if !expected_components.insert(component.component.as_str())
            || !expected_namespaces.insert(component.namespace.as_str())
            || !expected_native_export_prefixes.insert(component.native_export_prefix.as_str())
            || !expected_sentinels.insert(component.identity_export.as_str())
        {
            bail!("duplicate component, namespace, native export prefix, or sentinel in OHOS facade inventory");
        }
        let contract = contracts
            .iter()
            .find(|contract| contract.component == component.component)
            .with_context(|| {
                format!(
                    "OHOS component `{}` is missing its exact facade contract",
                    component.component
                )
            })?;
        if !contract_components.contains(component.component.as_str())
            || inventory_contracts.get(component.contract_file.as_str())
                != Some(&component.contract_sha256.as_str())
            || contract.namespace != component.namespace
            || contract.native_export_prefix != component.native_export_prefix
            || component.native_export_prefix
                != uniffi_bindgen::interface::native_export_prefix_for_component(
                    &component.component,
                )
        {
            bail!(
                "OHOS component `{}` is not paired with its checksummed facade contract",
                component.component
            );
        }
        let matches = raw_sentinels
            .iter()
            .filter(|def| def.name == component.identity_export)
            .collect::<Vec<_>>();
        let [sentinel] = matches.as_slice() else {
            bail!(
                "compiled OHOS bridge is missing unique identity sentinel `{}`",
                component.identity_export
            );
        };
        let expected = format!("function {}(): string", component.identity_export);
        if normalize_raw_contract_text(&sentinel.def) != normalize_raw_contract_text(&expected) {
            bail!(
                "compiled OHOS bridge identity sentinel `{}` has an invalid raw signature",
                component.identity_export
            );
        }
    }
    for sentinel in raw_sentinels {
        if !expected_sentinels.contains(sentinel.name.as_str()) {
            bail!(
                "compiled OHOS bridge contains unbound identity sentinel `{}`",
                sentinel.name
            );
        }
    }
    Ok(())
}

fn preflight_exact_schema_version(
    bytes: &[u8],
    field: &str,
    expected: u64,
    label: &str,
) -> Result<()> {
    let value: Value = serde_json::from_slice(bytes)
        .with_context(|| format!("parsing {label} schema-version probe"))?;
    let value = value.as_object().and_then(|object| object.get(field));
    match value.and_then(Value::as_u64) {
        Some(version) if version == expected => Ok(()),
        Some(version) => {
            bail!("unsupported {field} in {label}: expected {expected}, got {version}")
        }
        None => {
            let got = value
                .map(Value::to_string)
                .unwrap_or_else(|| "missing".to_string());
            bail!("unsupported {field} in {label}: expected {expected}, got {got}");
        }
    }
}

fn parse_harmony_facade_contract(bytes: &[u8], path: &Utf8Path) -> Result<HarmonyFacadeContract> {
    preflight_exact_schema_version(
        bytes,
        "facadeContractSchemaVersion",
        FACADE_CONTRACT_SCHEMA_VERSION,
        &format!("OHOS facade contract {path}"),
    )?;
    let contract: HarmonyFacadeContract = serde_json::from_slice(bytes)
        .with_context(|| format!("parsing exact OHOS facade contract schema in {path}"))?;
    validate_harmony_facade_contract_schema(&contract, path)?;
    Ok(contract)
}

fn validate_harmony_facade_contract_schema(
    contract: &HarmonyFacadeContract,
    path: &Utf8Path,
) -> Result<()> {
    if uniffi_bindgen::interface::validate_harmony_component_identity(
        &contract.component,
        &contract.namespace,
    )
    .is_err()
        || contract.native_export_prefix
            != uniffi_bindgen::interface::native_export_prefix_for_component(&contract.component)
    {
        bail!("OHOS facade contract {path} has an invalid component identity");
    }
    for output in &contract.output_streams {
        validate_harmony_output_stream_contract_schema(
            output,
            &contract.native_export_prefix,
            path,
        )?;
    }
    for input in &contract.input_streams {
        validate_harmony_input_stream_contract_schema(input, &contract.native_export_prefix, path)?;
    }
    Ok(())
}

fn validate_harmony_output_stream_contract_schema(
    output: &HarmonyOutputStreamContract,
    native_export_prefix: &str,
    path: &Utf8Path,
) -> Result<()> {
    for name in [
        &output.function,
        &output.next_function,
        &output.cancel_function,
        &output.stream_factory,
        &output.pull_class,
        &output.step_type,
    ] {
        validate_arkts_export_identifier(name).with_context(|| {
            format!("invalid generated identifier `{name}` in OHOS facade contract {path}")
        })?;
    }
    for argument in &output.arguments {
        validate_arkts_export_identifier(&argument.name)?;
        argument.r#type.validate(path, true, native_export_prefix)?;
    }
    let function_short_name = output.stream_factory.strip_suffix("Stream").with_context(|| {
        format!(
            "OHOS facade contract {path} has an output stream factory `{}` without the Stream suffix",
            output.stream_factory
        )
    })?;
    let expected =
        uniffi_bindgen_javascript::flavors::napi::ohos_raw_output_stream_names_for_prefix(
            native_export_prefix,
            function_short_name,
        );
    if output.function != expected.function
        || output.next_function != expected.next_function
        || output.cancel_function != expected.cancel_function
        || output.step_type != expected.step_type
    {
        bail!(
            "OHOS facade contract {path} has raw output-stream names that do not exactly match nativeExportPrefix `{native_export_prefix}`"
        );
    }
    output
        .item_type
        .validate(path, true, native_export_prefix)?;
    output
        .error_type
        .validate(path, false, native_export_prefix)
}

fn validate_harmony_input_stream_contract_schema(
    input: &HarmonyInputStreamContract,
    native_export_prefix: &str,
    path: &Utf8Path,
) -> Result<()> {
    for name in [
        &input.suffix,
        &input.next_type,
        &input.writer_class,
        &input.source_class,
        &input.channel_class,
        &input.factory,
    ] {
        validate_arkts_export_identifier(name).with_context(|| {
            format!("invalid generated identifier `{name}` in OHOS facade contract {path}")
        })?;
    }
    if input.canonical.is_empty()
        || input.canonical.len() > 64 * 1024
        || !input
            .canonical
            .bytes()
            .all(|byte| byte.is_ascii() && !byte.is_ascii_control())
    {
        bail!("OHOS facade contract {path} has an invalid canonical input descriptor");
    }
    let expected = stable_facade_fingerprint(&input.canonical);
    if input.fingerprint != expected || !input.suffix.ends_with(&format!("Fingerprint{expected}")) {
        bail!(
            "OHOS facade contract {path} has a mismatched input descriptor fingerprint for `{}`",
            input.suffix
        );
    }
    input
        .item_type
        .validate(path, false, native_export_prefix)?;
    input
        .error_type
        .validate(path, false, native_export_prefix)?;
    if input.source_class != format!("{}InputSource", input.suffix)
        || input.writer_class != format!("{}InputWriter", input.suffix)
        || input.channel_class != format!("{}InputChannel", input.suffix)
        || input.factory != format!("create{}InputChannel", input.suffix)
        || input.next_type
            != uniffi_bindgen_javascript::flavors::napi::ohos_raw_input_next_type_for_prefix(
                native_export_prefix,
                &input.suffix,
            )
    {
        bail!(
            "OHOS facade contract {path} has inconsistent generated names for input descriptor `{}`",
            input.suffix
        );
    }
    Ok(())
}

fn stable_facade_fingerprint(value: &str) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in value.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn validate_harmony_facade_contract_owners(
    contract: &HarmonyFacadeContract,
    identities: &BTreeMap<&str, (&str, &str)>,
    path: &Utf8Path,
) -> Result<()> {
    for output in &contract.output_streams {
        output.item_type.validate_owners(identities, path)?;
        output.error_type.validate_owners(identities, path)?;
        for argument in &output.arguments {
            argument.r#type.validate_owners(identities, path)?;
        }
    }
    for input in &contract.input_streams {
        input.item_type.validate_owners(identities, path)?;
        input.error_type.validate_owners(identities, path)?;
    }
    Ok(())
}

/// A named descriptor's owner is part of the frozen facade contract, not a
/// hint for a later global type lookup.  Check the declaration against the
/// exact canonical sidecar for that owner so equally named types in another
/// component cannot satisfy it accidentally.
fn validate_harmony_facade_contract_owner_type_references(
    contract: &HarmonyFacadeContract,
    owner_type_names: &BTreeMap<String, BTreeSet<String>>,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    path: &Utf8Path,
) -> Result<()> {
    for output in &contract.output_streams {
        validate_descriptor_owner_type_references(
            &output.item_type,
            owner_type_names,
            owner_native_export_prefixes,
            path,
        )?;
        validate_descriptor_owner_type_references(
            &output.error_type,
            owner_type_names,
            owner_native_export_prefixes,
            path,
        )?;
        for argument in &output.arguments {
            validate_descriptor_owner_type_references(
                &argument.r#type,
                owner_type_names,
                owner_native_export_prefixes,
                path,
            )?;
        }
    }
    for input in &contract.input_streams {
        validate_descriptor_owner_type_references(
            &input.item_type,
            owner_type_names,
            owner_native_export_prefixes,
            path,
        )?;
        validate_descriptor_owner_type_references(
            &input.error_type,
            owner_type_names,
            owner_native_export_prefixes,
            path,
        )?;
    }
    Ok(())
}

fn validate_descriptor_owner_type_references(
    descriptor: &HarmonyTypeDescriptor,
    owner_type_names: &BTreeMap<String, BTreeSet<String>>,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    path: &Utf8Path,
) -> Result<()> {
    match descriptor {
        HarmonyTypeDescriptor::Named { owner, name } => {
            let names = owner_type_names.get(&owner.component).with_context(|| {
                format!(
                    "named type `{name}` in {path} has an owner component `{}` without a canonical sidecar",
                    owner.component
                )
            })?;
            let native_export_prefix = owner_native_export_prefixes
                .get(&owner.component)
                .with_context(|| {
                    format!(
                        "named type `{name}` in {path} has an owner component `{}` without a native export prefix",
                        owner.component
                    )
                })?;
            let raw_name = uniffi_bindgen_javascript::native_exports::native_export_name_for_prefix(
                native_export_prefix,
                name,
            );
            if !names.contains(&raw_name) {
                bail!(
                    "named type `{name}` in {path} is not declared as raw `{raw_name}` by owner component `{}`'s canonical sidecar",
                    owner.component,
                );
            }
        }
        HarmonyTypeDescriptor::Optional { inner }
        | HarmonyTypeDescriptor::Sequence { inner }
        | HarmonyTypeDescriptor::Set { inner } => {
            validate_descriptor_owner_type_references(
                inner,
                owner_type_names,
                owner_native_export_prefixes,
                path,
            )?;
        }
        HarmonyTypeDescriptor::Number
        | HarmonyTypeDescriptor::Bigint
        | HarmonyTypeDescriptor::Boolean
        | HarmonyTypeDescriptor::String
        | HarmonyTypeDescriptor::ArrayBuffer
        | HarmonyTypeDescriptor::InputSource { .. } => {}
    }
    Ok(())
}

impl HarmonyTypeDescriptor {
    fn validate(
        &self,
        path: &Utf8Path,
        allow_input: bool,
        native_export_prefix: &str,
    ) -> Result<()> {
        match self {
            Self::Named { owner, name } => {
                uniffi_bindgen::interface::validate_harmony_component_identity(
                    &owner.component,
                    &owner.namespace,
                )
                .with_context(|| {
                    format!("OHOS facade contract {path} has an invalid named type owner")
                })?;
                validate_arkts_export_identifier(name).with_context(|| {
                    format!("invalid named type `{name}` in OHOS facade contract {path}")
                })
            }
            Self::Optional { inner } | Self::Sequence { inner } | Self::Set { inner } => {
                inner.validate(path, false, native_export_prefix)
            }
            Self::InputSource { suffix, next_type } => {
                if !allow_input {
                    bail!("nested input source is not allowed in OHOS facade contract {path}");
                }
                validate_arkts_export_identifier(suffix)?;
                validate_arkts_export_identifier(next_type)?;
                if next_type
                    != &uniffi_bindgen_javascript::flavors::napi::ohos_raw_input_next_type_for_prefix(
                        native_export_prefix,
                        suffix,
                    )
                {
                    bail!(
                        "OHOS facade contract {path} has an input source next type that does not exactly match nativeExportPrefix `{native_export_prefix}`"
                    );
                }
                Ok(())
            }
            Self::Number | Self::Bigint | Self::Boolean | Self::String | Self::ArrayBuffer => {
                Ok(())
            }
        }
    }

    fn validate_owners(
        &self,
        identities: &BTreeMap<&str, (&str, &str)>,
        path: &Utf8Path,
    ) -> Result<()> {
        match self {
            Self::Named { owner, name } => {
                let (namespace, native_export_prefix) = identities
                    .get(owner.component.as_str())
                    .with_context(|| {
                        format!(
                            "named type `{name}` in {path} has an owner component `{}` absent from the host facade bundle",
                            owner.component
                        )
                    })?;
                if *namespace != owner.namespace
                    || *native_export_prefix
                        != uniffi_bindgen::interface::native_export_prefix_for_component(
                            &owner.component,
                        )
                {
                    bail!(
                        "named type `{name}` in {path} has an owner identity that does not exactly match the host facade bundle"
                    );
                }
            }
            Self::Optional { inner } | Self::Sequence { inner } | Self::Set { inner } => {
                inner.validate_owners(identities, path)?;
            }
            Self::Number
            | Self::Bigint
            | Self::Boolean
            | Self::String
            | Self::ArrayBuffer
            | Self::InputSource { .. } => {}
        }
        Ok(())
    }

    fn public_type(&self) -> String {
        match self {
            Self::Number => "number".into(),
            Self::Bigint => "bigint".into(),
            Self::Boolean => "boolean".into(),
            Self::String => "string".into(),
            Self::ArrayBuffer => "ArrayBuffer".into(),
            Self::Named { name, .. } => name.clone(),
            Self::Optional { inner } => {
                format!("{} | undefined | null", inner.public_type())
            }
            Self::Sequence { inner } => format!("Array<{}>", inner.public_type()),
            Self::Set { inner } => format!("Set<{}>", inner.public_type()),
            Self::InputSource { suffix, .. } => format!("{suffix}InputSource"),
        }
    }

    fn raw_type(
        &self,
        owner_native_export_prefixes: &BTreeMap<String, String>,
        local_native_export_prefix: &str,
        canonical_raw_stream_names: bool,
    ) -> Result<String> {
        match self {
            Self::InputSource { next_type, .. } => Ok(format!(
                "{}<{next_type}>",
                raw_input_stream_type_name(local_native_export_prefix, canonical_raw_stream_names,)
            )),
            Self::Named { owner, name } => {
                let native_export_prefix = owner_native_export_prefixes
                    .get(&owner.component)
                    .with_context(|| {
                        format!(
                            "Harmony named type `{name}` has owner component `{}` without a native export prefix",
                            owner.component
                        )
                    })?;
                Ok(
                    uniffi_bindgen_javascript::native_exports::native_export_name_for_prefix(
                        native_export_prefix,
                        name,
                    ),
                )
            }
            Self::Optional { inner } => Ok(format!(
                "{} | undefined | null",
                inner.raw_type(
                    owner_native_export_prefixes,
                    local_native_export_prefix,
                    canonical_raw_stream_names,
                )?
            )),
            Self::Sequence { inner } => Ok(format!(
                "Array<{}>",
                inner.raw_type(
                    owner_native_export_prefixes,
                    local_native_export_prefix,
                    canonical_raw_stream_names,
                )?
            )),
            Self::Set { inner } => Ok(format!(
                "Set<{}>",
                inner.raw_type(
                    owner_native_export_prefixes,
                    local_native_export_prefix,
                    canonical_raw_stream_names,
                )?
            )),
            Self::Number | Self::Bigint | Self::Boolean | Self::String | Self::ArrayBuffer => {
                Ok(self.public_type())
            }
        }
    }
}

fn raw_input_stream_type_name(
    native_export_prefix: &str,
    canonical_raw_stream_names: bool,
) -> String {
    if canonical_raw_stream_names {
        uniffi_bindgen_javascript::flavors::napi::ohos_raw_input_stream_type_for_prefix(
            native_export_prefix,
        )
    } else {
        "UniffiInputStream".to_string()
    }
}

fn raw_input_next_type_name(
    native_export_prefix: &str,
    suffix: &str,
    canonical_raw_stream_names: bool,
) -> String {
    if canonical_raw_stream_names {
        uniffi_bindgen_javascript::flavors::napi::ohos_raw_input_next_type_for_prefix(
            native_export_prefix,
            suffix,
        )
    } else {
        format!("UniffiInputStream{suffix}Next")
    }
}

fn validate_output_stream_raw_contract(
    defs: &[TypeDefLine],
    output: &HarmonyOutputStreamContract,
    native_export_prefix: &str,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    canonical_raw_stream_names: bool,
) -> Result<()> {
    let arguments = output
        .arguments
        .iter()
        .map(|argument| {
            Ok(format!(
                "{}: {}",
                argument.name,
                argument.r#type.raw_type(
                    owner_native_export_prefixes,
                    native_export_prefix,
                    canonical_raw_stream_names,
                )?
            ))
        })
        .collect::<Result<Vec<_>>>()?
        .join(", ");
    require_raw_function_signature(
        defs,
        &output.function,
        &format!("function {}({arguments}): bigint", output.function),
    )?;
    require_raw_function_signature(
        defs,
        &output.next_function,
        &format!(
            "function {}(handle: bigint): Promise<{}>",
            output.next_function, output.step_type
        ),
    )?;
    require_raw_function_signature(
        defs,
        &output.cancel_function,
        &format!("function {}(handle: bigint): void", output.cancel_function),
    )?;
    let next = require_unique_type_def(defs, &output.step_type)?;
    if next.kind != "interface" {
        bail!(
            "Harmony stream next type `{}` must be a raw interface, got `{}`",
            output.step_type,
            next.kind
        );
    }
    let expected = format!(
        "kind: string\nvalue?: {}\nerror?: {}",
        output.item_type.raw_type(
            owner_native_export_prefixes,
            native_export_prefix,
            canonical_raw_stream_names,
        )?,
        output.error_type.raw_type(
            owner_native_export_prefixes,
            native_export_prefix,
            canonical_raw_stream_names,
        )?
    );
    if normalize_raw_contract_text(&next.def) != normalize_raw_contract_text(&expected) {
        bail!(
            "Harmony stream next envelope `{}` (`{}`) does not match expected `{expected}` for item type `{}`",
            output.step_type,
            next.def,
            output.item_type.public_type()
        );
    }
    Ok(())
}

fn validate_descriptor_type_references(
    descriptor: &HarmonyTypeDescriptor,
    raw_types: &BTreeSet<String>,
    local_native_export_prefix: &str,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    canonical_raw_stream_names: bool,
) -> Result<()> {
    match descriptor {
        HarmonyTypeDescriptor::Named { owner, name } => {
            let native_export_prefix = owner_native_export_prefixes
                .get(&owner.component)
                .with_context(|| {
                    format!(
                        "Harmony facade type descriptor references owner component `{}` without a native export prefix",
                        owner.component
                    )
                })?;
            let raw_name = uniffi_bindgen_javascript::native_exports::native_export_name_for_prefix(
                native_export_prefix,
                name,
            );
            if !raw_types.contains(&raw_name) {
                bail!("Harmony facade type descriptor references missing raw type `{raw_name}`");
            }
        }
        HarmonyTypeDescriptor::Optional { inner }
        | HarmonyTypeDescriptor::Sequence { inner }
        | HarmonyTypeDescriptor::Set { inner } => {
            validate_descriptor_type_references(
                inner,
                raw_types,
                local_native_export_prefix,
                owner_native_export_prefixes,
                canonical_raw_stream_names,
            )?;
        }
        HarmonyTypeDescriptor::InputSource { suffix, next_type } => {
            let expected = raw_input_next_type_name(
                local_native_export_prefix,
                suffix,
                canonical_raw_stream_names,
            );
            if next_type != &expected || !raw_types.contains(next_type) {
                bail!("Harmony input source descriptor references missing next type `{next_type}`");
            }
        }
        HarmonyTypeDescriptor::Number
        | HarmonyTypeDescriptor::Bigint
        | HarmonyTypeDescriptor::Boolean
        | HarmonyTypeDescriptor::String
        | HarmonyTypeDescriptor::ArrayBuffer => {}
    }
    Ok(())
}

fn validate_input_stream_raw_contract(
    defs: &[TypeDefLine],
    input: &HarmonyInputStreamContract,
    native_export_prefix: &str,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    canonical_raw_stream_names: bool,
) -> Result<()> {
    let input_stream_name =
        raw_input_stream_type_name(native_export_prefix, canonical_raw_stream_names);
    let input_stream = require_unique_type_def(defs, &input_stream_name)?;
    if input_stream.kind != "interface" {
        bail!("Harmony input stream bridge must be an exact `{input_stream_name}` interface");
    }
    validate_unique_named_input_stream_interface(
        &format!(
            "export interface {input_stream_name}<T> {{\n{}\n}}",
            input_stream.def
        ),
        &input_stream_name,
    )?;
    let next = require_unique_type_def(defs, &input.next_type)?;
    if next.kind != "interface" {
        bail!(
            "Harmony input next type `{}` must be a raw interface, got `{}`",
            input.next_type,
            next.kind
        );
    }
    let expected = format!(
        "ok: boolean\ndone?: boolean\nvalue?: {}\nerror?: {}",
        input.item_type.raw_type(
            owner_native_export_prefixes,
            native_export_prefix,
            canonical_raw_stream_names,
        )?,
        input.error_type.raw_type(
            owner_native_export_prefixes,
            native_export_prefix,
            canonical_raw_stream_names,
        )?
    );
    if normalize_raw_contract_text(&next.def) != normalize_raw_contract_text(&expected) {
        bail!(
            "Harmony input next envelope `{}` does not match its item/error descriptor",
            input.next_type
        );
    }
    Ok(())
}

fn declaration_tokens(source: &str) -> Result<Vec<String>> {
    const MAX_SOURCE_BYTES: usize = 1024 * 1024;
    const MAX_TOKENS: usize = 65_536;
    const MAX_LEXEME_BYTES: usize = 64 * 1024;
    const MAX_IDENTIFIER_BYTES: usize = 512;
    if source.len() > MAX_SOURCE_BYTES {
        bail!("OHOS raw declaration exceeds the {MAX_SOURCE_BYTES}-byte validation limit");
    }
    let bytes = source.as_bytes();
    let mut tokens = Vec::new();
    let mut index = 0usize;
    while index < bytes.len() {
        let byte = bytes[index];
        if byte.is_ascii_whitespace() {
            index += 1;
            continue;
        }
        if byte == b'/' && bytes.get(index + 1) == Some(&b'/') {
            let start = index;
            index += 2;
            while index < bytes.len() && bytes[index] != b'\n' {
                index += 1;
            }
            if index - start > MAX_LEXEME_BYTES {
                bail!("line comment in OHOS raw declaration exceeds the validation limit");
            }
            continue;
        }
        if byte == b'/' && bytes.get(index + 1) == Some(&b'*') {
            let start = index;
            index += 2;
            let mut closed = false;
            while index + 1 < bytes.len() {
                if bytes[index] == b'*' && bytes[index + 1] == b'/' {
                    index += 2;
                    closed = true;
                    break;
                }
                index += 1;
            }
            if !closed {
                bail!("unterminated comment in OHOS raw declaration");
            }
            if index - start > MAX_LEXEME_BYTES {
                bail!("block comment in OHOS raw declaration exceeds the validation limit");
            }
            continue;
        }
        if matches!(byte, b'\'' | b'"' | b'`') {
            let start = index;
            let quote = byte;
            index += 1;
            let mut closed = false;
            while index < bytes.len() {
                if bytes[index] == b'\\' {
                    index = (index + 2).min(bytes.len());
                    continue;
                }
                if bytes[index] == quote {
                    index += 1;
                    closed = true;
                    break;
                }
                index += 1;
            }
            if !closed {
                bail!("unterminated string literal in OHOS raw declaration");
            }
            if index - start > MAX_LEXEME_BYTES {
                bail!("string literal in OHOS raw declaration exceeds the validation limit");
            }
            continue;
        }
        if byte.is_ascii_alphabetic() || matches!(byte, b'_' | b'$') {
            let start = index;
            index += 1;
            while index < bytes.len()
                && (bytes[index].is_ascii_alphanumeric() || matches!(bytes[index], b'_' | b'$'))
            {
                index += 1;
            }
            if index - start > MAX_IDENTIFIER_BYTES {
                bail!("identifier in OHOS raw declaration exceeds the validation limit");
            }
            tokens.push(source[start..index].to_string());
            if tokens.len() > MAX_TOKENS {
                bail!("OHOS raw declaration exceeds the token validation limit");
            }
            continue;
        }
        tokens.push((byte as char).to_string());
        if tokens.len() > MAX_TOKENS {
            bail!("OHOS raw declaration exceeds the token validation limit");
        }
        index += 1;
    }
    Ok(tokens)
}

fn validate_unique_input_stream_interface(source: &str) -> Result<()> {
    validate_unique_named_input_stream_interface(source, "UniffiInputStream")
}

fn validate_unique_named_input_stream_interface(source: &str, interface_name: &str) -> Result<()> {
    const MAX_NESTING: usize = 128;
    const MAX_INTERFACE_TOKENS: usize = 4096;
    let tokens = declaration_tokens(source)?;
    let mut bodies = Vec::new();
    let mut index = 0usize;
    let mut depth = 0usize;
    while index < tokens.len() {
        if tokens[index] == "{" {
            if depth >= MAX_NESTING {
                bail!("OHOS raw declaration exceeds the nesting validation limit");
            }
            depth += 1;
            index += 1;
            continue;
        }
        if tokens[index] == "}" {
            depth = depth
                .checked_sub(1)
                .context("unmatched closing brace in OHOS raw declaration")?;
            index += 1;
            continue;
        }
        let exported = depth == 0
            && tokens.get(index).is_some_and(|token| token == "export")
            && tokens
                .get(index + 1)
                .is_some_and(|token| token == "interface")
            && tokens
                .get(index + 2)
                .is_some_and(|token| token == interface_name);
        let unexported = depth == 0
            && tokens.get(index).is_some_and(|token| token == "interface")
            && tokens
                .get(index + 1)
                .is_some_and(|token| token == interface_name);
        if unexported {
            bail!("`{interface_name}<T>` must be a top-level exported interface");
        }
        if !exported {
            index += 1;
            continue;
        }
        let header = &tokens[index + 3..];
        if header.get(0).map(String::as_str) != Some("<")
            || header.get(1).map(String::as_str) != Some("T")
            || header.get(2).map(String::as_str) != Some(">")
            || header.get(3).map(String::as_str) != Some("{")
        {
            bail!("Harmony input stream requires exactly `export interface {interface_name}<T>`");
        }
        let body_start = index + 7;
        let mut cursor = body_start;
        let mut braces = 1usize;
        while cursor < tokens.len() && braces > 0 {
            if tokens[cursor] == "{" {
                if braces >= MAX_NESTING {
                    bail!("OHOS input stream interface exceeds the nesting validation limit");
                }
                braces += 1;
            } else if tokens[cursor] == "}" {
                braces -= 1;
            }
            cursor += 1;
            if cursor - body_start > MAX_INTERFACE_TOKENS {
                bail!("OHOS input stream interface exceeds the token validation limit");
            }
        }
        if braces != 0 {
            bail!("unterminated `UniffiInputStream<T>` interface");
        }
        bodies.push(tokens[body_start..cursor - 1].to_vec());
        index = cursor;
    }
    if depth != 0 {
        bail!("unmatched opening brace in OHOS raw declaration");
    }
    let [body] = bodies.as_slice() else {
        bail!(
            "Harmony input stream requires exactly one top-level `export interface {interface_name}<T>`, found {}",
            bodies.len()
        );
    };
    let patterns = [
        ["handle", ":", "number"].as_slice(),
        [
            "next", "(", "error", ":", "Error", "|", "null", ",", "handle", ":", "number", ")",
            ":", "Promise", "<", "T", ">",
        ]
        .as_slice(),
        [
            "cancel", "(", "error", ":", "Error", "|", "null", ",", "handle", ":", "number", ")",
            ":", "void",
        ]
        .as_slice(),
    ];
    let mut used = [false; 3];
    let mut cursor = 0usize;
    while cursor < body.len() {
        while body.get(cursor).is_some_and(|token| token == ";") {
            cursor += 1;
        }
        if cursor == body.len() {
            break;
        }
        let mut matched = false;
        for (pattern_index, pattern) in patterns.iter().enumerate() {
            if !used[pattern_index]
                && body
                    .get(cursor..cursor + pattern.len())
                    .is_some_and(|actual| {
                        actual
                            .iter()
                            .map(String::as_str)
                            .eq(pattern.iter().copied())
                    })
            {
                used[pattern_index] = true;
                cursor += pattern.len();
                matched = true;
                break;
            }
        }
        if !matched {
            bail!("Harmony input stream interface has an extra or malformed member");
        }
    }
    if used != [true, true, true] {
        bail!("Harmony input stream interface is missing a required member");
    }
    Ok(())
}

fn require_raw_function_signature(defs: &[TypeDefLine], name: &str, expected: &str) -> Result<()> {
    let matches = defs
        .iter()
        .filter(|def| def.kind == "fn" && def.name == name)
        .collect::<Vec<_>>();
    let [actual] = matches.as_slice() else {
        bail!(
            "Harmony stream contract requires exactly one raw callable `{name}`, found {}",
            matches.len()
        );
    };
    if normalize_raw_contract_text(&actual.def) != normalize_raw_contract_text(expected) {
        bail!(
            "Harmony raw callable `{name}` has signature `{}`, expected `{expected}`",
            actual.def
        );
    }
    Ok(())
}

fn require_unique_type_def<'a>(defs: &'a [TypeDefLine], name: &str) -> Result<&'a TypeDefLine> {
    let matches = defs
        .iter()
        .filter(|def| def.kind != "fn" && def.name == name)
        .collect::<Vec<_>>();
    let [value] = matches.as_slice() else {
        bail!(
            "Harmony stream contract requires exactly one raw type `{name}`, found {}",
            matches.len()
        );
    };
    Ok(*value)
}

fn normalize_raw_contract_text(value: &str) -> String {
    let mut out = String::new();
    let mut token = String::new();
    let flush = |token: &mut String, out: &mut String| {
        if token.is_empty() {
            return;
        }
        out.push_str(token);
        token.clear();
    };
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '$' {
            token.push(ch);
        } else {
            flush(&mut token, &mut out);
            if !ch.is_whitespace() && ch != ';' {
                out.push(ch);
            }
        }
    }
    flush(&mut token, &mut out);
    out
}

impl HarmonyStreamFacade {
    fn new(
        defs: &[TypeDefLine],
        contracts: Vec<HarmonyFacadeContract>,
        raw_exports: &FacadeExports,
        canonical_raw_stream_names: bool,
    ) -> Result<Self> {
        validate_raw_type_def_uniqueness(defs)?;
        if contracts.is_empty() {
            return Ok(Self::default());
        }
        let raw_callables = raw_exports
            .callables
            .iter()
            .map(String::as_str)
            .collect::<BTreeSet<_>>();
        let raw_values = raw_exports
            .callables
            .iter()
            .chain(&raw_exports.classes)
            .cloned()
            .collect::<BTreeSet<_>>();
        let raw_types = collect_declared_type_names(defs);
        let raw_names = raw_values
            .union(&raw_types)
            .cloned()
            .collect::<BTreeSet<_>>();
        let raw_classes = defs
            .iter()
            .filter(|def| def.kind == "struct")
            .map(|def| def.name.as_str())
            .collect::<BTreeSet<_>>();
        let owner_native_export_prefixes = contracts
            .iter()
            .map(|contract| {
                (
                    contract.component.clone(),
                    contract.native_export_prefix.clone(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        if owner_native_export_prefixes.len() != contracts.len() {
            bail!("duplicate Harmony stream facade contract component identity");
        }
        for value in raw_values.intersection(&raw_types) {
            if !raw_classes.contains(value.as_str()) {
                bail!("Harmony raw N-API value/type name collision for `{value}` is ambiguous");
            }
        }
        let mut generated_names = BTreeSet::new();
        let mut input_by_component_and_suffix =
            BTreeMap::<(String, String), HarmonyInputStreamContract>::new();
        let mut components = BTreeSet::new();
        let mut package_hidden_next_envelopes = Vec::new();

        let has_outputs = contracts
            .iter()
            .any(|contract| !contract.output_streams.is_empty());
        let has_inputs = contracts
            .iter()
            .any(|contract| !contract.input_streams.is_empty());
        if has_outputs || has_inputs {
            for imported in ["BusinessError", "Callback", "ErrorCallback"] {
                if raw_types.contains(imported) {
                    bail!(
                        "Harmony raw N-API type `{imported}` collides with a required ArkTS platform type"
                    );
                }
            }
            for value in ["UniFfiInputFailure"] {
                insert_generated_name(value, "value", &raw_names, &mut generated_names)?;
            }
            for ty in ["UniFfiInputFailureData"] {
                insert_generated_name(ty, "type", &raw_names, &mut generated_names)?;
            }
        }
        if has_outputs {
            for ty in ["UniFfiStream", "UniFfiStreamResult"] {
                insert_generated_name(ty, "type", &raw_names, &mut generated_names)?;
            }
            insert_generated_name(
                "UniFfiStreamFailure",
                "value",
                &raw_names,
                &mut generated_names,
            )?;
        }
        for private in [
            "__uniffiFacadeContractDigest",
            "__uniffiFacadeContractDigestValue",
        ] {
            insert_generated_name(private, "private helper", &raw_names, &mut generated_names)?;
        }
        if has_outputs || has_inputs {
            for private in [
                "__UNIFFI_STREAM_CLIENT_MISUSE_CODE",
                "__UNIFFI_INPUT_FAILURE_CODE",
                "__UNIFFI_STREAM_IDLE",
                "__UNIFFI_STREAM_STARTING",
                "__UNIFFI_STREAM_ACTIVE",
                "__UNIFFI_STREAM_DONE",
                "__UNIFFI_STREAM_FAILED",
                "__UNIFFI_STREAM_CANCELLED",
                "__UniFfiInputFailureData",
                "__UniFfiInputClosedError",
                "__UniFfiPullStream",
                "__UniFfiStreamStep",
                "__UniFfiStreamResult",
                "__UniFfiPendingWrite",
                "__UniFfiInputSource",
                "__uniffiInputHandleSeed",
                "__uniffiStreamProtocolError",
                "__uniffiOutputStepHasOnly",
                "__uniffiStrictOutputStep",
            ] {
                insert_generated_name(private, "private helper", &raw_names, &mut generated_names)?;
            }
        }

        for contract in &contracts {
            validate_arkts_export_identifier(&contract.component.replace('-', "_"))?;
            if !components.insert(contract.component.as_str()) {
                bail!(
                    "duplicate Harmony stream facade contract for component `{}`",
                    contract.component
                );
            }
            for output in &contract.output_streams {
                validate_descriptor_type_references(
                    &output.item_type,
                    &raw_types,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                validate_descriptor_type_references(
                    &output.error_type,
                    &raw_types,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                for argument in &output.arguments {
                    validate_descriptor_type_references(
                        &argument.r#type,
                        &raw_types,
                        &contract.native_export_prefix,
                        &owner_native_export_prefixes,
                        canonical_raw_stream_names,
                    )?;
                }
                validate_output_stream_raw_contract(
                    defs,
                    output,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                for required in [
                    output.function.as_str(),
                    output.next_function.as_str(),
                    output.cancel_function.as_str(),
                ] {
                    if !raw_callables.contains(required) {
                        bail!(
                            "Harmony stream contract for `{}` requires missing raw N-API callable `{required}`",
                            output.function
                        );
                    }
                }
                if !raw_types.contains(&output.step_type) {
                    bail!(
                        "Harmony stream contract for `{}` requires missing native step type `{}`",
                        output.function,
                        output.step_type
                    );
                }
                let next_envelope = require_unique_type_def(defs, &output.step_type)?;
                if !package_hidden_next_envelopes.contains(next_envelope) {
                    package_hidden_next_envelopes.push(next_envelope.clone());
                }
                for value in [&output.stream_factory, &output.pull_class] {
                    let value =
                        self_or_contract_internal_name(contracts.len() > 1, contract, value);
                    insert_generated_name(&value, "value", &raw_names, &mut generated_names)?;
                }
                for argument in &output.arguments {
                    validate_arkts_export_identifier(&argument.name)?;
                    if let HarmonyTypeDescriptor::InputSource { suffix, next_type } =
                        &argument.r#type
                    {
                        let input = contract
                            .input_streams
                            .iter()
                            .find(|input| &input.suffix == suffix)
                            .with_context(|| {
                                format!(
                                    "Harmony output stream `{}` references unknown input source `{suffix}`",
                                    output.function
                                )
                            })?;
                        if &input.next_type != next_type {
                            bail!(
                                "Harmony output stream `{}` has mismatched input next type `{next_type}`",
                                output.function
                            );
                        }
                    }
                }
            }
            for input in &contract.input_streams {
                validate_descriptor_type_references(
                    &input.item_type,
                    &raw_types,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                validate_descriptor_type_references(
                    &input.error_type,
                    &raw_types,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                validate_input_stream_raw_contract(
                    defs,
                    input,
                    &contract.native_export_prefix,
                    &owner_native_export_prefixes,
                    canonical_raw_stream_names,
                )?;
                let input_stream_type = raw_input_stream_type_name(
                    &contract.native_export_prefix,
                    canonical_raw_stream_names,
                );
                if !raw_types.contains(&input_stream_type) {
                    bail!(
                        "Harmony input stream `{}` requires missing native `{input_stream_type}` declaration",
                        input.suffix,
                    );
                }
                if !raw_types.contains(&input.next_type) {
                    bail!(
                        "Harmony input stream `{}` requires missing native next type `{}`",
                        input.suffix,
                        input.next_type
                    );
                }
                if let Some(previous) = input_by_component_and_suffix.insert(
                    (contract.component.clone(), input.suffix.clone()),
                    input.clone(),
                ) {
                    if previous != *input {
                        bail!(
                            "Harmony input stream suffix collision for `{}` has incompatible item/error metadata",
                            input.suffix
                        );
                    }
                    continue;
                }
                for value in [
                    &input.writer_class,
                    &input.source_class,
                    &input.channel_class,
                    &input.factory,
                ] {
                    let value =
                        self_or_contract_internal_name(contracts.len() > 1, contract, value);
                    insert_generated_name(&value, "value", &raw_names, &mut generated_names)?;
                }
                insert_generated_name(
                    &self_or_contract_internal_name(
                        contracts.len() > 1,
                        contract,
                        &format!("__{}InputNextEnvelope", input.suffix),
                    ),
                    "private type",
                    &raw_names,
                    &mut generated_names,
                )?;
            }
        }
        let native_types = raw_types
            .into_iter()
            .filter(|name| !raw_exports.classes.contains(name))
            .collect();
        Ok(Self {
            contracts,
            native_types,
            package_hidden_next_envelopes,
            host_composite_identity: String::new(),
            component_identities: Vec::new(),
            owner_native_export_prefixes,
            canonical_raw_stream_names,
        })
    }

    fn value_exports(&self) -> Vec<String> {
        let mut values = BTreeSet::new();
        if self.has_outputs() {
            values.insert("UniFfiStreamFailure".to_string());
        }
        if self.has_inputs() {
            values.extend(["UniFfiInputFailure".to_string()]);
        }
        for output in self.outputs() {
            values.insert(output.stream_factory.clone());
        }
        for input in self.inputs() {
            values.insert(input.writer_class.clone());
            values.insert(input.source_class.clone());
            values.insert(input.channel_class.clone());
            values.insert(input.factory.clone());
        }
        values.into_iter().collect()
    }

    fn type_exports(&self) -> Vec<String> {
        let mut types = BTreeSet::new();
        if self.has_outputs() {
            types.extend(["UniFfiStream".to_string(), "UniFfiStreamResult".to_string()]);
        }
        if self.has_inputs() {
            types.insert("UniFfiInputFailureData".to_string());
        }
        types.into_iter().collect()
    }

    fn has_streams(&self) -> bool {
        self.has_outputs() || self.has_inputs()
    }

    fn is_composite(&self) -> bool {
        self.contracts.len() > 1
    }

    fn internal_name(&self, contract: &HarmonyFacadeContract, public_name: &str) -> String {
        if self.is_composite() {
            format!("__uniffi_{}_{}", contract.namespace, public_name)
        } else {
            public_name.to_string()
        }
    }

    fn output_internal_names(
        &self,
        contract: &HarmonyFacadeContract,
        output: &HarmonyOutputStreamContract,
    ) -> HarmonyOutputInternalNames {
        HarmonyOutputInternalNames {
            stream_factory: self.internal_name(contract, &output.stream_factory),
            pull_class: self.internal_name(contract, &output.pull_class),
        }
    }

    fn input_internal_names(
        &self,
        contract: &HarmonyFacadeContract,
        input: &HarmonyInputStreamContract,
    ) -> HarmonyInputInternalNames {
        HarmonyInputInternalNames {
            writer_class: self.internal_name(contract, &input.writer_class),
            source_class: self.internal_name(contract, &input.source_class),
            channel_class: self.internal_name(contract, &input.channel_class),
            factory: self.internal_name(contract, &input.factory),
            envelope: self.internal_name(contract, &format!("__{}InputNextEnvelope", input.suffix)),
        }
    }

    fn has_outputs(&self) -> bool {
        self.contracts
            .iter()
            .any(|contract| !contract.output_streams.is_empty())
    }

    fn has_inputs(&self) -> bool {
        self.contracts
            .iter()
            .any(|contract| !contract.input_streams.is_empty())
    }

    fn hides_package_value(&self, name: &str) -> bool {
        self.outputs().into_iter().any(|output| {
            [
                output.function.as_str(),
                output.next_function.as_str(),
                output.cancel_function.as_str(),
            ]
            .contains(&name)
        })
    }

    fn hides_package_def(&self, def: &TypeDefLine) -> bool {
        (def.kind == "fn" && self.hides_package_value(&def.name))
            || self
                .package_hidden_next_envelopes
                .iter()
                .any(|envelope| envelope == def)
    }

    fn hides_package_type_name(&self, name: &str) -> bool {
        self.outputs()
            .into_iter()
            .any(|output| output.step_type == name)
            || self
                .package_hidden_next_envelopes
                .iter()
                .any(|envelope| envelope.name == name)
    }

    fn outputs(&self) -> Vec<&HarmonyOutputStreamContract> {
        let mut outputs = self
            .contracts
            .iter()
            .flat_map(|contract| contract.output_streams.iter())
            .collect::<Vec<_>>();
        outputs.sort_by(|a, b| a.function.cmp(&b.function));
        outputs
    }

    fn outputs_with_contract(&self) -> Vec<(&HarmonyFacadeContract, &HarmonyOutputStreamContract)> {
        let mut outputs = self
            .contracts
            .iter()
            .flat_map(|contract| {
                contract
                    .output_streams
                    .iter()
                    .map(move |output| (contract, output))
            })
            .collect::<Vec<_>>();
        outputs.sort_by(|(left_contract, left), (right_contract, right)| {
            left_contract
                .component
                .cmp(&right_contract.component)
                .then_with(|| left.function.cmp(&right.function))
        });
        outputs
    }

    fn inputs(&self) -> Vec<&HarmonyInputStreamContract> {
        if self.is_composite() {
            return self
                .inputs_with_contract()
                .into_iter()
                .map(|(_, input)| input)
                .collect();
        }
        let mut inputs = BTreeMap::new();
        for contract in &self.contracts {
            for input in &contract.input_streams {
                inputs.entry(input.suffix.as_str()).or_insert(input);
            }
        }
        inputs.into_values().collect()
    }

    fn inputs_with_contract(&self) -> Vec<(&HarmonyFacadeContract, &HarmonyInputStreamContract)> {
        let mut inputs = self
            .contracts
            .iter()
            .flat_map(|contract| {
                contract
                    .input_streams
                    .iter()
                    .map(move |input| (contract, input))
            })
            .collect::<Vec<_>>();
        inputs.sort_by(|(left_contract, left), (right_contract, right)| {
            left_contract
                .component
                .cmp(&right_contract.component)
                .then_with(|| left.suffix.cmp(&right.suffix))
        });
        inputs
    }

    fn render_native_facade(
        &self,
        contract_digest: Option<&str>,
        export_owned_pull_classes: bool,
    ) -> String {
        let mut out = String::new();
        let has_contract_anchor = contract_digest.is_some();
        if let Some(contract_digest) = contract_digest {
            out.push_str(&format!(
                r#"

const __uniffiFacadeContractDigestValue: string = "{contract_digest}";
export function __uniffiFacadeContractDigest(): string {{
  return __uniffiFacadeContractDigestValue;
}}
__uniffiFacadeContractDigest();
"#,
            ));
        }
        if !self.has_streams() {
            return out;
        }
        out.push_str(
            r#"

// Harmony stream objects are confined to the ArkTS concurrency instance that creates them.
const __UNIFFI_STREAM_CLIENT_MISUSE_CODE: number = 1900002;
const __UNIFFI_INPUT_FAILURE_CODE: number = 1900003;

export interface UniFfiInputFailureData<E> {
  variant: string;
  detail: string;
  nativeError: E;
}

class __UniFfiInputFailureData<E> implements UniFfiInputFailureData<E> {
  variant: string;
  detail: string;
  nativeError: E;

  constructor(variant: string, detail: string, nativeError: E) {
    this.variant = variant;
    this.detail = detail;
    this.nativeError = nativeError;
  }
}

export class UniFfiInputFailure<E> extends Error implements BusinessError<UniFfiInputFailureData<E>> {
  code: number;
  data: UniFfiInputFailureData<E>;

  constructor(nativeError: E, message: string, variant: string) {
    super(message);
    this.name = 'UniFfiInputFailure';
    this.code = __UNIFFI_INPUT_FAILURE_CODE;
    this.data = new __UniFfiInputFailureData<E>(variant, message, nativeError);
  }
}

class __UniFfiInputClosedError extends Error {
  constructor() {
    super('UniFFI input stream is closed');
    this.name = 'UniFfiInputClosedError';
  }
}

export interface UniFfiStreamResult<T> {
  done: boolean;
  value?: T;
}

class __UniFfiStreamResult<T> implements UniFfiStreamResult<T> {
  done: boolean;
  value?: T;

  constructor(done: boolean, value?: T) {
    this.done = done;
    this.value = value;
  }
}

export interface UniFfiStream<T> {
  next(): Promise<UniFfiStreamResult<T>>;
  cancel(): Promise<void>;
}

export class UniFfiStreamFailure<E> extends Error {
  nativeError: E;

  constructor(nativeError: E) {
    super('UniFFI stream failed');
    this.name = 'UniFfiStreamFailure';
    this.nativeError = nativeError;
  }
}

class __UniFfiStreamStep<T, E> {
  kind: string;
  value?: T;
  error?: E;

  constructor(kind: string) {
    this.kind = kind;
  }
}

const __UNIFFI_STREAM_IDLE: number = 0;
const __UNIFFI_STREAM_STARTING: number = 1;
const __UNIFFI_STREAM_ACTIVE: number = 2;
const __UNIFFI_STREAM_DONE: number = 3;
const __UNIFFI_STREAM_FAILED: number = 4;
const __UNIFFI_STREAM_CANCELLED: number = 5;

function __uniffiStreamProtocolError(message: string): Error {
  const error: Error = new Error(message);
  error.name = 'UniFfiStreamProtocolError';
  return error;
}

function __uniffiOutputStepHasOnly(rawKeys: Array<string>, payload: string | null): boolean {
  const expectedLength: number = payload === null ? 1 : 2;
  if (rawKeys.length !== expectedLength) {
    return false;
  }
  let hasKind: boolean = false;
  let hasPayload: boolean = payload === null;
  for (let index: number = 0; index < rawKeys.length; index += 1) {
    const key: string = rawKeys[index];
    if (key === 'kind') {
      hasKind = true;
    } else if (payload !== null && key === payload) {
      hasPayload = true;
    } else {
      return false;
    }
  }
  return hasKind && hasPayload;
}

function __uniffiStrictOutputStep<T, E>(
  rawKeys: Array<string>,
  kind: string,
  value?: T,
  error?: E,
): __UniFfiStreamStep<T, E> {
  if (kind === 'item') {
    if (!__uniffiOutputStepHasOnly(rawKeys, 'value') || value === undefined || error !== undefined) {
      throw __uniffiStreamProtocolError('raw stream item step must contain only value');
    }
    const step: __UniFfiStreamStep<T, E> = new __UniFfiStreamStep<T, E>('item');
    step.value = value;
    return step;
  }
  if (kind === 'done') {
    if (!__uniffiOutputStepHasOnly(rawKeys, null) || value !== undefined || error !== undefined) {
      throw __uniffiStreamProtocolError('raw stream done step must not contain a payload');
    }
    return new __UniFfiStreamStep<T, E>('done');
  }
  if (kind === 'error') {
    if (!__uniffiOutputStepHasOnly(rawKeys, 'error') || value !== undefined || error === undefined) {
      throw __uniffiStreamProtocolError('raw stream error step must contain only error');
    }
    const step: __UniFfiStreamStep<T, E> = new __UniFfiStreamStep<T, E>('error');
    step.error = error;
    return step;
  }
  throw __uniffiStreamProtocolError('raw stream step must be item, done, or error');
}

abstract class __UniFfiPullStream<T, E> implements UniFfiStream<T> {
  private state: number = __UNIFFI_STREAM_IDLE;
  private handle: bigint = 0n;
  private hasHandle: boolean = false;
  private pulling: boolean = false;
  private cancelSent: boolean = false;
  private cancelled: boolean = false;
  private failure: Error | null = null;

  protected abstract startNative(): bigint;
  protected abstract nextNative(handle: bigint): Promise<__UniFfiStreamStep<T, E>>;
  protected abstract cancelNative(handle: bigint): void;

  async next(): Promise<UniFfiStreamResult<T>> {
    if (this.state === __UNIFFI_STREAM_DONE || this.cancelled) {
      return new __UniFfiStreamResult<T>(true);
    }
    if (this.state === __UNIFFI_STREAM_FAILED) {
      if (this.failure === null) {
        throw this.protocolError('failed stream has no recorded failure');
      }
      throw this.failure;
    }
    if (this.pulling || this.state === __UNIFFI_STREAM_STARTING) {
      throw this.clientMisuseError();
    }
    if (this.state === __UNIFFI_STREAM_IDLE) {
      this.state = __UNIFFI_STREAM_STARTING;
      try {
        this.handle = this.startNative();
        this.hasHandle = true;
        if (this.cancelled) {
          this.cancelNativeOnce();
          this.state = __UNIFFI_STREAM_CANCELLED;
          return new __UniFfiStreamResult<T>(true);
        }
        this.state = __UNIFFI_STREAM_ACTIVE;
      } catch (reason) {
        if (this.cancelled) {
          this.state = __UNIFFI_STREAM_CANCELLED;
          return new __UniFfiStreamResult<T>(true);
        }
        const failure: Error = reason as Error;
        this.state = __UNIFFI_STREAM_FAILED;
        this.recordFailure(failure);
        throw failure;
      }
    }
    if (this.state !== __UNIFFI_STREAM_ACTIVE) {
      return new __UniFfiStreamResult<T>(true);
    }
    this.pulling = true;
    try {
      const step: __UniFfiStreamStep<T, E> = await this.nextNative(this.handle);
      this.pulling = false;
      if (this.cancelled) {
        return new __UniFfiStreamResult<T>(true);
      }
      if (step.kind === 'item') {
        if (step.value === undefined) {
          throw this.protocolError('normalized stream item is missing value');
        }
        return new __UniFfiStreamResult<T>(false, step.value as T);
      }
      if (step.kind === 'done') {
        this.state = __UNIFFI_STREAM_DONE;
        return new __UniFfiStreamResult<T>(true);
      }
      if (step.kind === 'error' && step.error !== undefined) {
        const failure: Error = new UniFfiStreamFailure<E>(step.error) as Error;
        this.state = __UNIFFI_STREAM_FAILED;
        this.recordFailure(failure);
        throw failure;
      }
      throw this.protocolError('normalized stream step has an invalid kind');
    } catch (reason) {
      this.pulling = false;
      if (this.cancelled) {
        return new __UniFfiStreamResult<T>(true);
      }
      const failure: Error = reason instanceof Error
        ? reason
        : this.protocolError('raw stream adapter rejected with a non-Error value');
      if (this.state !== __UNIFFI_STREAM_FAILED) {
        this.failActive(failure);
      }
      throw failure;
    }
  }

  async cancel(): Promise<void> {
    if (this.state === __UNIFFI_STREAM_IDLE) {
      this.cancelled = true;
      this.state = __UNIFFI_STREAM_CANCELLED;
      return;
    }
    if (this.state === __UNIFFI_STREAM_STARTING || this.state === __UNIFFI_STREAM_ACTIVE) {
      this.cancelled = true;
      this.state = __UNIFFI_STREAM_CANCELLED;
      this.cancelNativeOnce();
    }
  }

  private failActive(reason: Error): void {
    if (this.state === __UNIFFI_STREAM_ACTIVE || this.state === __UNIFFI_STREAM_STARTING) {
      this.cancelNativeOnce();
    }
    this.state = __UNIFFI_STREAM_FAILED;
    this.recordFailure(reason);
  }

  private recordFailure(reason: Error): void {
    if (this.failure === null) {
      this.failure = reason;
    }
  }

  private cancelNativeOnce(): void {
    if (!this.hasHandle || this.cancelSent) {
      return;
    }
    this.cancelSent = true;
    try {
      this.cancelNative(this.handle);
    } catch (_ignored) {
    }
  }

  private clientMisuseError(): Error {
    const error: Error = new Error('UniFFI stream already has an in-flight next call');
    error.name = 'UniFfiStreamConcurrentNext';
    return error;
  }

  private protocolError(message: string): Error {
    return __uniffiStreamProtocolError(message);
  }
}

class __UniFfiPendingWrite<T> {
  item: T;
  resolve: Callback<void>;
  reject: ErrorCallback<Error>;

  constructor(item: T, resolve: Callback<void>, reject: ErrorCallback<Error>) {
    this.item = item;
    this.resolve = resolve;
    this.reject = reject;
  }
}

let __uniffiInputHandleSeed: number = 1;

abstract class __UniFfiInputSource<T, E, N> {
  readonly handle: number;
  readonly next = (_error: Error | null, handle: number): Promise<N> => this.pull(handle);
  readonly cancel = (_error: Error | null, handle: number): void => this.cancelFromNative(handle);
  private queue: Array<__UniFfiPendingWrite<T>> = new Array<__UniFfiPendingWrite<T>>();
  private waiting: Array<Callback<N>> = new Array<Callback<N>>();
  private ended: boolean = false;
  private cancelled: boolean = false;
  private failed: boolean = false;
  private failureDelivered: boolean = false;
  private failure: E | null = null;

  constructor() {
    this.handle = __uniffiInputHandleSeed;
    __uniffiInputHandleSeed += 1;
    if (__uniffiInputHandleSeed > 4294967295) {
      __uniffiInputHandleSeed = 1;
    }
  }

  protected abstract valueEnvelope(item: T): N;
  protected abstract doneEnvelope(): N;
  protected abstract errorEnvelope(error: E): N;

  write(item: T): Promise<void> {
    if (this.ended || this.cancelled || this.failed) {
      return Promise.reject(this.closedError());
    }
    if (this.waiting.length > 0) {
      const waiting: Callback<N> = this.waiting[0];
      this.waiting.splice(0, 1);
      waiting(this.valueEnvelope(item));
      return Promise.resolve();
    }
    return new Promise<void>((resolve, reject): void => {
      this.queue.push(new __UniFfiPendingWrite<T>(
        item,
        resolve as Callback<void>,
        reject as ErrorCallback<Error>
      ));
    });
  }

  end(): void {
    if (this.ended || this.cancelled || this.failed) {
      return;
    }
    this.ended = true;
    this.rejectQueued(this.closedError());
    this.resolveAllWaitingWithDone();
  }

  fail(error: UniFfiInputFailure<E>): void {
    if (this.ended || this.cancelled || this.failed) {
      return;
    }
    this.failed = true;
    this.failure = error.data.nativeError;
    this.rejectQueued(this.closedError());
    if (this.waiting.length > 0) {
      this.failureDelivered = true;
      while (this.waiting.length > 0) {
        const waiting: Callback<N> = this.waiting[0];
        this.waiting.splice(0, 1);
        waiting(this.errorEnvelope(error.data.nativeError));
      }
    }
  }

  private pull(handle: number): Promise<N> {
    if (handle !== this.handle) {
      return Promise.resolve(this.doneEnvelope());
    }
    if (this.queue.length > 0) {
      const pending: __UniFfiPendingWrite<T> = this.queue[0];
      this.queue.splice(0, 1);
      const envelope: N = this.valueEnvelope(pending.item);
      pending.resolve();
      return Promise.resolve(envelope);
    }
    if (this.failed && !this.failureDelivered) {
      this.failureDelivered = true;
      return Promise.resolve(this.errorEnvelope(this.failure as E));
    }
    if (this.ended || this.cancelled || (this.failed && this.failureDelivered)) {
      return Promise.resolve(this.doneEnvelope());
    }
    return new Promise<N>((resolve): void => {
      this.waiting.push(resolve as Callback<N>);
    });
  }

  private cancelFromNative(handle: number): void {
    if (handle !== this.handle || this.cancelled || this.ended || this.failed) {
      return;
    }
    this.cancelled = true;
    this.rejectQueued(this.closedError());
    this.resolveAllWaitingWithDone();
  }

  private resolveAllWaitingWithDone(): void {
    while (this.waiting.length > 0) {
      const waiting: Callback<N> = this.waiting[0];
      this.waiting.splice(0, 1);
      waiting(this.doneEnvelope());
    }
  }

  private rejectQueued(error: Error): void {
    while (this.queue.length > 0) {
      const pending: __UniFfiPendingWrite<T> = this.queue[0];
      this.queue.splice(0, 1);
      pending.reject(error);
    }
  }

  private closedError(): Error {
    return new __UniFfiInputClosedError();
  }
}
"#,
        );
        for (contract, input) in self.inputs_with_contract() {
            let names = self.input_internal_names(contract, input);
            out.push_str(&render_harmony_input_implementation(
                input,
                &names,
                &contract.native_export_prefix,
                &self.owner_native_export_prefixes,
                self.canonical_raw_stream_names,
            ));
        }
        for (contract, output) in self.outputs_with_contract() {
            let names = self.output_internal_names(contract, output);
            out.push_str(&render_harmony_output_implementation(
                output,
                &names,
                &contract.native_export_prefix,
                &self.owner_native_export_prefixes,
                self.canonical_raw_stream_names,
                self.is_composite() || export_owned_pull_classes,
                has_contract_anchor,
            ));
        }
        out
    }

    fn render_imports(&self, native_module: &str) -> String {
        if self.native_types.is_empty() && !self.has_streams() {
            return String::new();
        }
        let mut out = String::new();
        if !self.native_types.is_empty() {
            out.push_str("import type {\n");
            for name in &self.native_types {
                out.push_str(&format!("  {name},\n"));
            }
            out.push_str(&format!("}} from \"{native_module}\";\n"));
        }
        if self.has_streams() {
            out.push_str(
                "import type { BusinessError, Callback, ErrorCallback } from \"@kit.BasicServicesKit\";\n\n",
            );
        } else if !out.is_empty() {
            out.push('\n');
        }
        out
    }

    fn render_declarations(&self) -> String {
        if !self.has_streams() {
            return String::new();
        }
        let mut out = String::new();
        if self.has_outputs() {
            out.push_str(
                r#"

/** Stream objects must only be used from the ArkTS concurrency instance that created them. */
export interface UniFfiStreamResult<T> {
  done: boolean;
  value?: T;
}

export interface UniFfiStream<T> {
  next(): Promise<UniFfiStreamResult<T>>;
  cancel(): Promise<void>;
}

export declare class UniFfiStreamFailure<E> extends Error {
  nativeError: E;
  constructor(nativeError: E);
}
"#,
            );
        }
        if self.has_inputs() {
            out.push_str(
                r#"

export interface UniFfiInputFailureData<E> {
  variant: string;
  detail: string;
  nativeError: E;
}

export declare class UniFfiInputFailure<E> extends Error implements BusinessError<UniFfiInputFailureData<E>> {
  code: number;
  data: UniFfiInputFailureData<E>;
  constructor(nativeError: E, message: string, variant: string);
}
"#,
            );
        }
        for (contract, input) in self.inputs_with_contract() {
            let names = self.input_internal_names(contract, input);
            out.push_str(&render_harmony_input_declarations(
                input,
                &names,
                &contract.native_export_prefix,
                self.canonical_raw_stream_names,
            ));
        }
        for (contract, output) in self.outputs_with_contract() {
            let names = self.output_internal_names(contract, output);
            out.push_str(&render_harmony_output_declarations(output, &names));
        }
        out
    }

    fn declaration_imports(&self) -> &'static str {
        if self.has_inputs() {
            "import type { BusinessError, Callback, ErrorCallback } from \"@kit.BasicServicesKit\";\n\n"
        } else {
            ""
        }
    }

    fn render_contract_inventory(&self) -> Result<String> {
        let components = self
            .contracts
            .iter()
            .map(|contract| contract.component.clone())
            .collect::<Vec<_>>();
        let output_streams = self
            .outputs()
            .into_iter()
            .map(|output| {
                serde_json::json!({
                    "function": output.function,
                    "nextFunction": output.next_function,
                    "cancelFunction": output.cancel_function,
                    "streamFactory": output.stream_factory,
                    "pullClass": output.pull_class,
                    "stepType": output.step_type,
                    "itemType": output.item_type,
                    "errorType": output.error_type,
                    "arguments": output.arguments.iter().map(|argument| serde_json::json!({
                        "name": argument.name,
                        "type": argument.r#type,
                    })).collect::<Vec<_>>(),
                })
            })
            .collect::<Vec<_>>();
        let input_streams = self
            .inputs()
            .into_iter()
            .map(|input| {
                serde_json::json!({
                    "suffix": input.suffix,
                    "canonical": input.canonical,
                    "fingerprint": input.fingerprint,
                    "itemType": input.item_type,
                    "errorType": input.error_type,
                    "nextType": input.next_type,
                    "writerClass": input.writer_class,
                    "sourceClass": input.source_class,
                    "channelClass": input.channel_class,
                    "factory": input.factory,
                })
            })
            .collect::<Vec<_>>();
        serde_json::to_string_pretty(&serde_json::json!({
            "hspFacadeAggregateSchemaVersion": HSP_FACADE_AGGREGATE_SCHEMA_VERSION,
            "hostCompositeIdentity": self.host_composite_identity,
            "componentIdentities": self.component_identities,
            "components": components,
            "outputStreams": output_streams,
            "inputStreams": input_streams,
        }))
        .map_err(Into::into)
    }
}

fn collect_declared_type_names(defs: &[TypeDefLine]) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for def in defs {
        if !def.name.is_empty() && def.kind != "fn" {
            names.insert(def.name.clone());
        }
    }
    names
}

fn insert_generated_name(
    name: &str,
    kind: &str,
    raw_names: &BTreeSet<String>,
    generated: &mut BTreeSet<String>,
) -> Result<()> {
    validate_arkts_export_identifier(name)?;
    if raw_names.contains(name) || !generated.insert(name.to_string()) {
        bail!("Harmony generated stream {kind} name collision for `{name}`");
    }
    Ok(())
}

fn harmony_arguments(arguments: &[HarmonyFacadeArgument]) -> String {
    arguments
        .iter()
        .map(|argument| format!("{}: {}", argument.name, argument.r#type.public_type()))
        .collect::<Vec<_>>()
        .join(", ")
}

fn component_descriptor_public_type(
    descriptor: &HarmonyTypeDescriptor,
    current: &FacadeComponentProjection,
) -> String {
    match descriptor {
        HarmonyTypeDescriptor::Number => "number".to_string(),
        HarmonyTypeDescriptor::Bigint => "bigint".to_string(),
        HarmonyTypeDescriptor::Boolean => "boolean".to_string(),
        HarmonyTypeDescriptor::String => "string".to_string(),
        HarmonyTypeDescriptor::ArrayBuffer => "ArrayBuffer".to_string(),
        HarmonyTypeDescriptor::Named { owner, name } => {
            if owner.component == current.component {
                name.clone()
            } else {
                format!("{}.{}", owner.namespace, name)
            }
        }
        HarmonyTypeDescriptor::Optional { inner } => format!(
            "{} | undefined | null",
            component_descriptor_public_type(inner, current)
        ),
        HarmonyTypeDescriptor::Sequence { inner } => {
            format!(
                "Array<{}>",
                component_descriptor_public_type(inner, current)
            )
        }
        HarmonyTypeDescriptor::Set { inner } => {
            format!("Set<{}>", component_descriptor_public_type(inner, current))
        }
        HarmonyTypeDescriptor::InputSource { suffix, .. } => format!("{suffix}InputSource"),
    }
}

fn collect_component_descriptor_namespaces(
    descriptor: &HarmonyTypeDescriptor,
    current: &FacadeComponentProjection,
    namespaces: &mut BTreeSet<String>,
) {
    match descriptor {
        HarmonyTypeDescriptor::Named { owner, .. } => {
            if owner.component != current.component {
                namespaces.insert(owner.namespace.clone());
            }
        }
        HarmonyTypeDescriptor::Optional { inner }
        | HarmonyTypeDescriptor::Sequence { inner }
        | HarmonyTypeDescriptor::Set { inner } => {
            collect_component_descriptor_namespaces(inner, current, namespaces);
        }
        HarmonyTypeDescriptor::Number
        | HarmonyTypeDescriptor::Bigint
        | HarmonyTypeDescriptor::Boolean
        | HarmonyTypeDescriptor::String
        | HarmonyTypeDescriptor::ArrayBuffer
        | HarmonyTypeDescriptor::InputSource { .. } => {}
    }
}

fn component_harmony_arguments(
    arguments: &[HarmonyFacadeArgument],
    current: &FacadeComponentProjection,
) -> String {
    arguments
        .iter()
        .map(|argument| {
            format!(
                "{}: {}",
                argument.name,
                component_descriptor_public_type(&argument.r#type, current)
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn replace_arkts_identifiers(source: &str, replacements: &BTreeMap<String, String>) -> String {
    let mut out = String::with_capacity(source.len());
    let mut index = 0usize;
    let bytes = source.as_bytes();
    while index < bytes.len() {
        let byte = bytes[index];
        if byte.is_ascii_alphabetic() || matches!(byte, b'_' | b'$') {
            let start = index;
            index += 1;
            while bytes
                .get(index)
                .is_some_and(|byte| byte.is_ascii_alphanumeric() || matches!(*byte, b'_' | b'$'))
            {
                index += 1;
            }
            let identifier = &source[start..index];
            if let Some(replacement) = replacements.get(identifier) {
                out.push_str(replacement);
            } else {
                out.push_str(identifier);
            }
        } else {
            out.push(byte as char);
            index += 1;
        }
    }
    out
}

fn component_callable_public_type(
    raw_type: &str,
    replacements: &BTreeMap<String, String>,
) -> String {
    replace_arkts_identifiers(raw_type, replacements)
}

fn render_component_output_declarations(
    output: &HarmonyOutputStreamContract,
    current: &FacadeComponentProjection,
) -> String {
    format!(
        "\nexport declare function {}({}): UniFfiStream<{}>;\n",
        output.stream_factory,
        component_harmony_arguments(&output.arguments, current),
        component_descriptor_public_type(&output.item_type, current),
    )
}

fn component_output_callable_type(
    output: &HarmonyOutputStreamContract,
    current: &FacadeComponentProjection,
) -> String {
    format!(
        "({}) => UniFfiStream<{}>",
        component_harmony_arguments(&output.arguments, current),
        component_descriptor_public_type(&output.item_type, current),
    )
}

fn render_component_input_declarations(
    input: &HarmonyInputStreamContract,
    current: &FacadeComponentProjection,
) -> String {
    let _ = current;
    format!(
        r#"

export declare function {factory}(): {channel_class};
"#,
        channel_class = input.channel_class,
        factory = input.factory,
    )
}

fn component_input_callable_type(input: &HarmonyInputStreamContract) -> String {
    format!("() => {}", input.channel_class)
}

fn harmony_native_facade_arguments(
    arguments: &[HarmonyFacadeArgument],
    owner_native_export_prefixes: &BTreeMap<String, String>,
    local_native_export_prefix: &str,
    canonical_raw_stream_names: bool,
) -> String {
    arguments
        .iter()
        .map(|argument| {
            format!(
                "{}: {}",
                argument.name,
                harmony_native_facade_type(
                    &argument.r#type,
                    owner_native_export_prefixes,
                    local_native_export_prefix,
                    canonical_raw_stream_names,
                )
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn harmony_native_facade_type(
    descriptor: &HarmonyTypeDescriptor,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    local_native_export_prefix: &str,
    canonical_raw_stream_names: bool,
) -> String {
    if canonical_raw_stream_names {
        descriptor
            .raw_type(
                owner_native_export_prefixes,
                local_native_export_prefix,
                canonical_raw_stream_names,
            )
            .expect("validated Harmony stream raw type")
    } else {
        descriptor.public_type()
    }
}

fn harmony_argument_names(arguments: &[HarmonyFacadeArgument]) -> String {
    arguments
        .iter()
        .map(|argument| argument.name.as_str())
        .collect::<Vec<_>>()
        .join(", ")
}

fn render_harmony_output_implementation(
    output: &HarmonyOutputStreamContract,
    names: &HarmonyOutputInternalNames,
    local_native_export_prefix: &str,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    canonical_raw_stream_names: bool,
    export_pull_class: bool,
    include_contract_anchor: bool,
) -> String {
    let args = harmony_native_facade_arguments(
        &output.arguments,
        owner_native_export_prefixes,
        local_native_export_prefix,
        canonical_raw_stream_names,
    );
    let item_type = harmony_native_facade_type(
        &output.item_type,
        owner_native_export_prefixes,
        local_native_export_prefix,
        canonical_raw_stream_names,
    );
    let pass = harmony_argument_names(&output.arguments);
    let fields = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, argument)| {
            format!(
                "  private __arg{index}: {};\n",
                harmony_native_facade_type(
                    &argument.r#type,
                    owner_native_export_prefixes,
                    local_native_export_prefix,
                    canonical_raw_stream_names,
                )
            )
        })
        .collect::<String>();
    let assignments = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, argument)| format!("    this.__arg{index} = {};\n", argument.name))
        .collect::<String>();
    let call_args = if pass.is_empty() { String::new() } else { pass };
    let this_call_args = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, _argument)| format!("this.__arg{index}"))
        .collect::<Vec<_>>()
        .join(", ");
    let contract_anchor = if include_contract_anchor {
        "  __uniffiFacadeContractDigest();\n"
    } else {
        ""
    };
    format!(
        r#"

{pull_export}class {pull_class} extends __UniFfiPullStream<{item_type}, {error_type}> {{
{fields}  constructor({args}) {{
    super();
{assignments}  }}

  protected startNative(): bigint {{
    return native.{function}({this_call_args});
  }}

  protected async nextNative(handle: bigint): Promise<__UniFfiStreamStep<{item_type}, {error_type}>> {{
    const raw: {step_type} = await native.{next_function}(handle);
    const rawKeys: Array<string> = Object.keys(raw);
    return __uniffiStrictOutputStep<{item_type}, {error_type}>(
      rawKeys,
      raw.kind,
      raw.value,
      raw.error,
    );
  }}

  protected cancelNative(handle: bigint): void {{
    native.{cancel_function}(handle);
  }}
}}

export function {stream_factory}({args}): UniFfiStream<{item_type}> {{
{contract_anchor}  return new {pull_class}({call_args});
}}
"#,
        pull_class = names.pull_class,
        pull_export = if export_pull_class { "export " } else { "" },
        item_type = item_type,
        error_type = harmony_native_facade_type(
            &output.error_type,
            owner_native_export_prefixes,
            local_native_export_prefix,
            canonical_raw_stream_names,
        ),
        fields = fields,
        args = args,
        assignments = assignments,
        function = output.function,
        call_args = call_args,
        this_call_args = this_call_args,
        next_function = output.next_function,
        step_type = output.step_type,
        cancel_function = output.cancel_function,
        stream_factory = names.stream_factory,
        contract_anchor = contract_anchor,
    )
}

fn render_harmony_input_implementation(
    input: &HarmonyInputStreamContract,
    names: &HarmonyInputInternalNames,
    local_native_export_prefix: &str,
    owner_native_export_prefixes: &BTreeMap<String, String>,
    canonical_raw_stream_names: bool,
) -> String {
    let envelope = &names.envelope;
    let item_type = harmony_native_facade_type(
        &input.item_type,
        owner_native_export_prefixes,
        local_native_export_prefix,
        canonical_raw_stream_names,
    );
    let error_type = harmony_native_facade_type(
        &input.error_type,
        owner_native_export_prefixes,
        local_native_export_prefix,
        canonical_raw_stream_names,
    );
    let input_stream_type =
        raw_input_stream_type_name(local_native_export_prefix, canonical_raw_stream_names);
    format!(
        r#"

class {envelope} implements {next_type} {{
  ok: boolean;
  done?: boolean;
  value?: {item_type};
  error?: {error_type};

  constructor(ok: boolean) {{
    this.ok = ok;
  }}
}}

export class {source_class}
  extends __UniFfiInputSource<{item_type}, {error_type}, {envelope}>
  implements {input_stream_type}<{next_type}> {{
  protected valueEnvelope(item: {item_type}): {envelope} {{
    const result: {envelope} = new {envelope}(true);
    result.done = false;
    result.value = item;
    return result;
  }}

  protected doneEnvelope(): {envelope} {{
    const result: {envelope} = new {envelope}(true);
    result.done = true;
    return result;
  }}

  protected errorEnvelope(error: {error_type}): {envelope} {{
    const result: {envelope} = new {envelope}(false);
    result.error = error;
    return result;
  }}
}}

export class {writer_class} {{
  private source: {source_class};

  constructor(source: {source_class}) {{
    this.source = source;
  }}

  write(item: {item_type}): Promise<void> {{
    return this.source.write(item);
  }}

  end(): void {{
    this.source.end();
  }}

  fail(error: UniFfiInputFailure<{error_type}>): void {{
    this.source.fail(error);
  }}
}}

export class {channel_class} {{
  writer: {writer_class};
  source: {source_class};

  constructor() {{
    this.source = new {source_class}();
    this.writer = new {writer_class}(this.source);
  }}
}}

export function {factory}(): {channel_class} {{
  return new {channel_class}();
}}
"#,
        envelope = envelope,
        next_type = input.next_type,
        item_type = item_type,
        error_type = error_type,
        source_class = names.source_class,
        writer_class = names.writer_class,
        channel_class = names.channel_class,
        factory = names.factory,
        input_stream_type = input_stream_type,
    )
}

fn render_harmony_output_declarations(
    output: &HarmonyOutputStreamContract,
    names: &HarmonyOutputInternalNames,
) -> String {
    let args = harmony_arguments(&output.arguments);
    let item_type = output.item_type.public_type();
    format!(
        r#"

export declare function {stream_factory}({args}): UniFfiStream<{item_type}>;
"#,
        item_type = item_type,
        args = args,
        stream_factory = names.stream_factory,
    )
}

fn render_harmony_input_declarations(
    input: &HarmonyInputStreamContract,
    names: &HarmonyInputInternalNames,
    local_native_export_prefix: &str,
    canonical_raw_stream_names: bool,
) -> String {
    let item_type = input.item_type.public_type();
    let error_type = input.error_type.public_type();
    let input_stream_type =
        raw_input_stream_type_name(local_native_export_prefix, canonical_raw_stream_names);
    format!(
        r#"

export declare class {source_class} implements {input_stream_type}<{next_type}> {{
  readonly handle: number;
  next(error: Error | null, handle: number): Promise<{next_type}>;
  cancel(error: Error | null, handle: number): void;
}}

export declare class {writer_class} {{
  constructor(source: {source_class});
  write(item: {item_type}): Promise<void>;
  end(): void;
  fail(error: UniFfiInputFailure<{error_type}>): void;
}}

export declare class {channel_class} {{
  writer: {writer_class};
  source: {source_class};
  constructor();
}}

export declare function {factory}(): {channel_class};
"#,
        source_class = names.source_class,
        next_type = input.next_type,
        writer_class = names.writer_class,
        item_type = item_type,
        error_type = error_type,
        channel_class = names.channel_class,
        factory = names.factory,
        input_stream_type = input_stream_type,
    )
}

fn validate_arkts_export_identifier(name: &str) -> Result<()> {
    let mut chars = name.chars();
    let valid = chars
        .next()
        .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_' || ch == '$')
        && chars.all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '$')
        && !is_arkts_reserved_word(name);
    if !valid {
        bail!(
            "N-API export `{name}` is not a legal non-reserved ArkTS binding identifier; rename the UniFFI item"
        );
    }
    Ok(())
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct TypeDefLine {
    kind: String,
    name: String,
    def: String,
    type_parameters: Vec<String>,
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
enum OhosTypeDefKind {
    Interface,
    StringEnum,
    Type,
    Struct,
    Fn,
}

impl OhosTypeDefKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Interface => "interface",
            Self::StringEnum => "string_enum",
            Self::Type => "type",
            Self::Struct => "struct",
            Self::Fn => "fn",
        }
    }
}

/// The only raw type definition format accepted after the N-API producer has
/// finished.  The explicit prefix is part of the protocol and prevents JSON
/// fragments or free-form TypeScript from becoming a second input language.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct CanonicalOhosTypeDef {
    kind: OhosTypeDefKind,
    name: String,
    def: String,
    #[serde(rename = "typeParameters")]
    type_parameters: Vec<String>,
}

/// The raw input-stream declaration is the sole generic OHOS sidecar type.
/// Its exact name is owned by the checked facade contract for one component;
/// it is never recovered from a sidecar suffix, bridge sentinel, or an
/// unqualified legacy type name.
#[derive(Clone, Debug, Eq, PartialEq)]
struct RawInputStreamTypeExpectation {
    name: String,
    required: bool,
}

impl RawInputStreamTypeExpectation {
    fn from_contract(contract: &HarmonyFacadeContract) -> Self {
        Self {
            name: uniffi_bindgen_javascript::flavors::napi::ohos_raw_input_stream_type_for_prefix(
                &contract.native_export_prefix,
            ),
            required: !contract.input_streams.is_empty(),
        }
    }

    fn validate_coverage(&self, count: usize, path: &str) -> Result<()> {
        if self.required && count != 1 {
            bail!(
                "canonical OHOS type sidecar {path} must declare exactly one raw input-stream type `{}` because its owning facade contract declares inputStreams",
                self.name
            );
        }
        Ok(())
    }
}

impl CanonicalOhosTypeDef {
    fn validate_producer_shape(
        &self,
        input_stream_type: Option<&RawInputStreamTypeExpectation>,
    ) -> Result<bool> {
        let Some(input_stream_type) = input_stream_type else {
            if self.name == "UniffiInputStream" {
                bail!(
                    "canonical OHOS raw input-stream type `UniffiInputStream` has no owning facade contract"
                );
            }
            if self.type_parameters.is_empty() {
                return Ok(false);
            }
            bail!(
                "canonical OHOS type `{}` must not declare typeParameters without an owning facade contract",
                self.name
            );
        };
        if self.name == input_stream_type.name {
            if !input_stream_type.required {
                bail!(
                    "canonical OHOS raw input-stream type `{}` is not allowed because its owning facade contract declares no inputStreams",
                    input_stream_type.name
                );
            }
            if self.kind == OhosTypeDefKind::Interface
                && self.type_parameters.len() == 1
                && self.type_parameters[0] == "T"
            {
                return Ok(true);
            }
            bail!(
                "canonical OHOS raw input-stream type `{}` must be an interface with exact typeParameters [\"T\"]",
                input_stream_type.name
            );
        }
        if self.type_parameters.is_empty() {
            Ok(false)
        } else {
            bail!(
                "canonical OHOS type `{}` must not declare typeParameters; only raw input-stream type `{}` from its owning facade contract may use exact [\"T\"]",
                self.name,
                input_stream_type.name
            )
        }
    }
}

impl From<CanonicalOhosTypeDef> for TypeDefLine {
    fn from(value: CanonicalOhosTypeDef) -> Self {
        Self {
            kind: value.kind.as_str().to_string(),
            name: value.name,
            def: value.def,
            type_parameters: value.type_parameters,
        }
    }
}

fn parse_canonical_ohos_type_defs(
    source: &[u8],
    path: &str,
    input_stream_type: &RawInputStreamTypeExpectation,
) -> Result<Vec<TypeDefLine>> {
    let mut definitions = Vec::new();
    let mut input_stream_type_count = 0usize;
    for (line_number, line) in BufReader::new(Cursor::new(source)).lines().enumerate() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let record = line.trim().strip_prefix("type_def:").with_context(|| {
            format!(
                "OHOS type definition emitted at {path}:{} must use the exact `type_def:` envelope",
                line_number + 1
            )
        })?;
        let definition: CanonicalOhosTypeDef = serde_json::from_str(record).with_context(|| {
            format!(
                "parsing exact OHOS type definition emitted at {path}:{}",
                line_number + 1
            )
        })?;
        if definition.validate_producer_shape(Some(input_stream_type))? {
            input_stream_type_count += 1;
        }
        definitions.push(definition.into());
    }
    input_stream_type.validate_coverage(input_stream_type_count, path)?;
    validate_raw_type_def_uniqueness(&definitions)?;
    Ok(definitions)
}

fn validate_type_def_declared_name(def: &TypeDefLine) -> Result<()> {
    validate_arkts_export_identifier(&def.name)?;
    if def.kind == "fn" {
        let declaration = def.def.trim();
        let declared = declaration
            .strip_prefix("function ")
            .and_then(|rest| rest.split_once('(').map(|(name, _)| name.trim()))
            .filter(|name| !name.is_empty())
            .with_context(|| {
                format!(
                    "raw OHOS callable `{}` has a malformed declaration `{}`",
                    def.name, def.def
                )
            })?;
        if declared != def.name {
            bail!(
                "raw OHOS callable metadata name `{}` does not match declaration `{declared}`",
                def.name
            );
        }
    }
    Ok(())
}

fn validate_raw_type_def_uniqueness(defs: &[TypeDefLine]) -> Result<()> {
    let mut names = BTreeMap::<String, (&str, &str, &[String])>::new();
    for def in defs {
        validate_type_def_declared_name(def)?;
        let name = def.name.as_str();
        if let Some((kind, body, type_parameters)) = names.insert(
            name.to_string(),
            (&def.kind, &def.def, &def.type_parameters),
        ) {
            if kind != def.kind || body != def.def || type_parameters != &def.type_parameters[..] {
                bail!(
                    "duplicate raw OHOS declaration `{name}` has incompatible declarations: `{kind}` `{body}` versus `{}` `{}`",
                    def.kind,
                    def.def
                );
            }
            bail!(
                "duplicate raw OHOS declaration for `{name}` repeats `{}` `{}`",
                def.kind,
                def.def
            );
        }
    }
    Ok(())
}

fn collect_type_defs(
    type_dir: &Utf8Path,
    files: &[FacadeInventoryFile],
    defs: &mut Vec<TypeDefLine>,
) -> Result<()> {
    let mut files = files.iter().collect::<Vec<_>>();
    files.sort_by(|left, right| left.file.cmp(&right.file));
    for entry in files {
        let path = type_dir.join(&entry.file);
        let bytes = read_verified_regular_file(&path)?;
        if sha256_bytes(&bytes) != entry.sha256 {
            bail!("OHOS type definition changed before consumption: {path}");
        }
        for line in BufReader::new(Cursor::new(bytes)).lines() {
            let line = line?;
            if let Some(def) = parse_type_def_line(&line)? {
                defs.push(def);
            }
        }
    }
    validate_raw_type_def_uniqueness(defs)?;
    Ok(())
}

fn collect_owned_type_defs(
    type_dir: &Utf8Path,
    inventory: &FacadeTypeInventory,
) -> Result<Vec<OwnedFacadeTypeDefs>> {
    if inventory.facade_mode != "required" {
        return Ok(Vec::new());
    }
    let entries = inventory
        .type_definitions
        .iter()
        .map(|entry| (entry.file.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut owned = Vec::new();
    for component in &inventory.components {
        let file = format!("{}.ohos-extra-types.d.ts", component.component);
        let entry = entries.get(file.as_str()).with_context(|| {
            format!(
                "OHOS facade inventory is missing canonical sidecar `{file}` for component `{}`",
                component.component
            )
        })?;
        let path = type_dir.join(&entry.file);
        let bytes = read_verified_regular_file(&path)?;
        if sha256_bytes(&bytes) != entry.sha256 {
            bail!("OHOS type definition changed before consumption: {path}");
        }
        let contract = read_inventory_component_contract(type_dir, inventory, component)?;
        let input_stream_type = RawInputStreamTypeExpectation::from_contract(&contract);
        let defs = parse_canonical_ohos_type_defs(&bytes, &path.to_string(), &input_stream_type)?;
        owned.push(OwnedFacadeTypeDefs::new(component, defs)?);
    }
    let flattened = owned
        .iter()
        .flat_map(|component| component.defs.iter().cloned())
        .collect::<Vec<_>>();
    validate_raw_type_def_uniqueness(&flattened)?;
    Ok(owned)
}

fn parse_type_def_line(line: &str) -> Result<Option<TypeDefLine>> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    let record = trimmed.strip_prefix("type_def:").with_context(|| {
        format!("OHOS type definition must use the exact `type_def:` envelope, got `{trimmed}`")
    })?;
    let definition: CanonicalOhosTypeDef = serde_json::from_str(record)
        .with_context(|| format!("parsing exact OHOS type definition JSON line: {trimmed}"))?;
    definition.validate_producer_shape(None)?;
    Ok(Some(definition.into()))
}

fn render_index_d_ts(defs: Vec<TypeDefLine>) -> String {
    if defs.is_empty() {
        return TYPE_HEADER.to_string();
    }
    let mut out = TYPE_HEADER.to_string();
    let mut defs = defs;
    defs.sort_by(|a, b| a.name.cmp(&b.name));
    for def in defs {
        out.push_str(&pretty_type_def(&def));
        out.push('\n');
    }
    out
}

fn pretty_type_def(def: &TypeDefLine) -> String {
    let mut out = String::new();
    let declare = "export declare";
    let definition = match def.kind.as_str() {
        // These definitions contain TypeScript type positions. Do not run
        // enum/string-enum members through the mapper: `Buffer = ...` is a
        // user-visible member name, not a byte-buffer type.
        "interface" | "type" | "struct" | "fn" => render_ohos_type_fragment(&def.def),
        _ => def.def.clone(),
    };
    match def.kind.as_str() {
        "interface" => out.push_str(&format!(
            "export interface {}{} {{\n{}\n}}",
            def.name,
            render_type_parameters(&def.type_parameters),
            definition
        )),
        "string_enum" => {
            let values = definition
                .split(',')
                .filter_map(|entry| entry.split_once('=').map(|(_, rhs)| rhs.trim()))
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>();
            let values = if values.is_empty() {
                definition.clone()
            } else {
                values.join(" | ")
            };
            out.push_str(&format!("export type {} = {};", def.name, values));
        }
        "type" => {
            if let Some(rendered) = render_arkts_payload_union(&def.name, &definition) {
                out.push_str(&rendered);
            } else {
                out.push_str(&format!(
                    "export type {}{} =\n{}",
                    def.name,
                    render_type_parameters(&def.type_parameters),
                    definition
                ));
            }
        }
        "struct" => {
            out.push_str(&format!(
                "{declare} class {}{} {{\n{}\n}}",
                def.name,
                render_type_parameters(&def.type_parameters),
                definition
            ));
        }
        "fn" => out.push_str(&format!("{declare} {definition}")),
        _ => out.push_str(&definition),
    }
    out
}

fn render_type_parameters(parameters: &[String]) -> String {
    if parameters.is_empty() {
        String::new()
    } else {
        format!("<{}>", parameters.join(", "))
    }
}

fn render_arkts_payload_union(name: &str, definition: &str) -> Option<String> {
    let mut bodies = Vec::new();
    let mut start = None;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    for (index, ch) in definition.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        if ch == '\'' || ch == '"' {
            quote = Some(ch);
            continue;
        }
        match ch {
            '{' => {
                if depth == 0 {
                    start = Some(index + ch.len_utf8());
                }
                depth += 1;
            }
            '}' if depth > 0 => {
                depth -= 1;
                if depth == 0 {
                    bodies.push(definition[start?..index].trim().to_string());
                    start = None;
                }
            }
            _ => {}
        }
    }
    if depth != 0 || bodies.is_empty() {
        return None;
    }

    let mut interfaces = Vec::new();
    for body in bodies {
        let fields = split_top_level_fields(&body)?;
        let tag = fields.iter().find_map(|field| {
            let (key, value) = field.split_once(':')?;
            if key.trim() != "type" {
                return None;
            }
            let value = value.trim();
            (value.len() >= 2
                && ((value.starts_with('\'') && value.ends_with('\''))
                    || (value.starts_with('"') && value.ends_with('"'))))
            .then(|| value[1..value.len() - 1].to_string())
        })?;
        let suffix = arkts_type_suffix(&tag)?;
        let interface_name = format!("{name}{suffix}");
        validate_arkts_export_identifier(&interface_name).ok()?;
        interfaces.push((interface_name, fields));
    }

    let mut out = String::new();
    for (interface_name, fields) in &interfaces {
        out.push_str(&format!("export interface {interface_name} {{\n"));
        for field in fields {
            out.push_str("  ");
            out.push_str(field.trim());
            if !field.trim_end().ends_with(';') {
                out.push(';');
            }
            out.push('\n');
        }
        out.push_str("}\n");
    }
    out.push_str(&format!(
        "export type {name} = {};",
        interfaces
            .iter()
            .map(|(interface_name, _)| interface_name.as_str())
            .collect::<Vec<_>>()
            .join(" | ")
    ));
    Some(out)
}

fn split_top_level_fields(body: &str) -> Option<Vec<String>> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    for (index, ch) in body.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        if ch == '\'' || ch == '"' {
            quote = Some(ch);
            continue;
        }
        match ch {
            '<' | '(' | '[' | '{' => depth += 1,
            '>' | ')' | ']' | '}' if depth > 0 => depth -= 1,
            ',' if depth == 0 => {
                let field = body[start..index].trim();
                if !field.is_empty() {
                    out.push(field.to_string());
                }
                start = index + ch.len_utf8();
            }
            _ => {}
        }
    }
    if quote.is_some() || depth != 0 {
        return None;
    }
    let field = body[start..].trim();
    if !field.is_empty() {
        out.push(field.to_string());
    }
    (!out.is_empty()).then_some(out)
}

fn arkts_type_suffix(tag: &str) -> Option<String> {
    let mut out = String::new();
    let mut uppercase_next = true;
    for ch in tag.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                out.push(ch.to_ascii_uppercase());
            } else {
                out.push(ch);
            }
            uppercase_next = false;
        } else {
            uppercase_next = true;
        }
    }
    (!out.is_empty()).then_some(out)
}

